// A trade saved under the old (reversed) lists still holds a pattern that its
// setup no longer offers. The chips render from cfg.patterns alone, so that
// value would show nothing selected — present in the database, invisible on
// screen, and impossible to correct. Appending it keeps it visible and
// changeable; it drops out of the list the moment a listed one is picked.
function _confluencePatternChoices(cfg, current){
  const list = (cfg && cfg.patterns) ? cfg.patterns.slice() : [];
  if(current && !list.includes(current)) list.push(current);
  return list;
}

// Color tier for a "Sequence" pick (Which 5m HL/LH is this?) by its index in
// the select list — 1st/2nd green, 3rd orange, 4th/5th red. Shared by the
// live chip picker and the read-only Trade View display so both agree.
function _sequenceTint(idx){
  return idx <= 1 ? 'var(--win)' : (idx === 2 ? 'var(--warn)' : 'var(--loss)');
}

// Confluence can be filled in on a Pending Setup (before it's ever
// journaled) or added/edited later directly on an already-journaled trade
// (old trades from before this feature existed have no confluence yet) —
// one target object instead of two parallel id variables keeps save/close
// from needing to guess which flow opened the modal.
// Shared by the real Confluence modal (setConfluenceAnswer) and the
// Notebook "Bread & Butter" reference tool (setBbAnswer) — one row builder
// so Yes/No/Retest/Almost items and multi-choice "Sequence" items (select)
// render identically in both places.
function _renderConfluenceItemRow(it, i, ans, setAnswerFn){
  if(it.select){
    // Later position in the sequence = more red (a 4th/5th HL/LH is further
    // into an already-extended move than a 1st/2nd) — same tint used for
    // both the chip's outline and its filled/active state.
    const chips = it.select.map((opt, idx) => {
      const tint = _sequenceTint(idx);
      const isActive = ans === opt;
      const style = isActive ? `border-color:${tint};background:${tint};color:#fff;` : `border-color:${tint};color:${tint};`;
      return `<span class="cfl-pattern-chip ${isActive?'active':''}" style="${style}" onclick="${setAnswerFn}(${i},'${opt}')">${opt}</span>`;
    }).join('');
    return `
      <div class="cfl-yn-item cfl-select-item ${!ans?'cfl-unanswered':''}">
        <span class="cfl-yn-label"><span class="cfl-yn-tag">${it.tag}</span>${it.text}</span>
        <span class="cfl-select-chips">${chips}</span>
      </div>
    `;
  }
  return `
    <div class="cfl-yn-item ${it.exec?'cfl-execution':''} ${!ans?'cfl-unanswered':''}">
      <span class="cfl-yn-label"><span class="cfl-yn-tag">${it.tag}</span>${it.text}</span>
      <span class="cfl-yn-buttons">
        <button type="button" class="cfl-yn-btn ${it.invert?'cfl-no':'cfl-yes'} ${ans==='yes'?'active':''}" onclick="${setAnswerFn}(${i},'yes')">Yes</button>
        ${it.retest ? `<button type="button" class="cfl-yn-btn cfl-retest ${ans==='retest'?'active':''}" onclick="${setAnswerFn}(${i},'retest')">Retest</button>` : ''}
        ${(it.exec || it.almost) ? `<button type="button" class="cfl-yn-btn cfl-almost ${ans==='almost'?'active':''}" onclick="${setAnswerFn}(${i},'almost')">Almost</button>` : ''}
        <button type="button" class="cfl-yn-btn ${it.invert?'cfl-yes':'cfl-no'} ${ans==='no'?'active':''}" onclick="${setAnswerFn}(${i},'no')">No</button>
      </span>
    </div>
  `;
}

// "Yes"/"Retest" both count as full confluence credit (a retest entry after
// a real signal isn't a lesser entry, just a different timing), "Almost"
// is half, a "Sequence"-style pick counts full just for being answered.
// For an "invert" item (Left/Right Hand Present, where No is the good
// outcome) the credit flips too — a green "No" is a hit, a red "Yes" is a
// miss — otherwise a fully clean checklist would never actually show full marks.
// Chart Pattern counts as one full point: an A+ setup has a recognisable
// pattern behind it, so a checklist with every indicator answered but no
// pattern should read 5/6, not 5/5 — the missing point is the signal.
// Some checklist answers settle another question outright, so you aren't asked
// to confirm something already known. A MACD that has just broken the zero
// line is by definition sitting AT it — so "Break = Yes" means "far from the
// zero line = No", not Yes.
//
// The map form ({ targetId: valueToSet }) rather than a plain list, because
// the implied answer isn't always the same as the trigger — here Yes implies
// No. Keyed by `id` so question wording can change without breaking the link.
//
// Deliberately one-directional and non-destructive: it only fills a BLANK, and
// only fires on Yes. Answering No implies nothing (not having crossed says
// nothing about distance), and taking a Yes back to No never wipes what was
// filled — second-guessing an answer already on screen is worse than the
// keystroke it saved.
function _applyConfluenceImplications(items, answers, changedIdx){
  const it = items[changedIdx];
  if(!it || !it.impliesWhenYes || answers[changedIdx] !== 'yes') return;
  Object.entries(it.impliesWhenYes).forEach(([id, value]) => {
    const target = items.findIndex(x => x.id === id);
    // An explicit answer stands — the trader looked at the chart, the tool
    // did not.
    if(target >= 0 && answers[target] === undefined) answers[target] = value;
  });
}

// How much credit a multi-choice (Sequence) answer earns. Mirrors the chip
// colours exactly — 1st/2nd green, 3rd orange, 4th/5th red — because until
// now ANY answer scored a full point, so a 5th HL and a 1st HL came out
// identical. The chip said red, the auto-flag said "Ignored Trend" and the
// Trade Review said "missed", while the score said full marks; three of the
// four agreed and the one that fed the Warning Signs and the Review did not.
function _selectCredit(it, ans){
  const idx = it.select.indexOf(ans);
  if(idx < 0) return 0;
  return idx <= 1 ? 1 : (idx === 2 ? 0.5 : 0);
}

function _confluenceProgress(items, answers, chartPatternPresent){
  const answeredValues = Object.values(answers);
  let done = chartPatternPresent ? 1 : 0;
  items.forEach((it, i) => {
    const ans = answers[i];
    if(ans === undefined) return;
    if(it.select){ done += _selectCredit(it, ans); return; }
    if(it.invert){
      if(ans === 'no') done += 1;
      else if(ans === 'almost') done += 0.5;
      return;
    }
    if(ans === 'yes' || ans === 'retest') done += 1;
    else if(ans === 'almost') done += 0.5;
  });
  return { total: items.length + 1, done, unanswered: items.length - answeredValues.length };
}

// Auto-detects rule violations straight from the confluence checklist so
// Rules Followed / Unfollowed Rules don't rely on remembering to fill them
// in by hand. Matched by item TEXT, not index — item order/count differs
// per Trade Type|Pattern Type key, and "30 mins Invalidation Play" uses
// different wording entirely, so it's correctly untouched by this.
//
// The MACD-cross and 1H-territory checks are written as OR across the
// up/down (or bull/bear) phrasing on purpose: a single checklist only ever
// contains ONE of the two (Long has "upward"/"Bull", Short has
// "downward"/"Bear") — requiring both to equal "no" could never fire.
// Additive only: this only ADDS a "No" + checked reasons, it never clears
// a value the trader already set (e.g. by fixing the confluence answers
// after the fact) — undoing an auto-flag is a manual, deliberate action.
function _autoUnfollowedRules(cfg, answers, chartPatternPresent){
  // Opted out per setup — Invalidation Play carries this. Returned before any
  // rule runs, so the confluence bar, the 3min break, the MACD cross, the
  // divergence hand and the HTF bias are all skipped, not just some of them.
  if(cfg.noAutoRules) return new Set();

  const byText = (text) => {
    const i = cfg.items.findIndex(it => it.text === text);
    return i === -1 ? undefined : answers[i];
  };
  const reasons = new Set();

  // A PERCENTAGE, and set PER SETUP. Two separate reasons for that:
  //
  // The old rule was a raw "score <= 5", which meant something different on
  // every checklist — 56% on a 9-slot list but 71% on the 7-slot Invalidation
  // Play, so a 5/7 (the better read) was flagged while a 6/9 (the weaker one)
  // was not. Every question added since made the bar quietly looser too,
  // because the 5 never moved.
  //
  // And one shared percentage isn't right either: a 5-minute scalp and a
  // 1-hour swing are different trades that deserve different bars. Each setup
  // carries its own `minConfluencePct`; DEFAULT_MIN_CONFLUENCE_PCT only
  // applies to a setup that hasn't named one.
  const bar = Number.isFinite(cfg.minConfluencePct) ? cfg.minConfluencePct : DEFAULT_MIN_CONFLUENCE_PCT;
  const { done, total } = _confluenceProgress(cfg.items, answers, chartPatternPresent);
  if(total > 0 && (done / total * 100) < bar){
    reasons.add('Lack of Confluence');
    reasons.add('Non-BnB Setup');
  }

  // A 3min breakdown (Long) or breakout (Short) against the position IS the
  // setup invalidating, and answering Yes has always meant it happened and the
  // trade was held — which is what "Held Through Invalidation" records, in the
  // words of the decision rather than of the trigger.
  //
  // It is no longer a breach, and it now feeds an A/B test, so the one thing to
  // know: this fills in the HELD arm. On a trade where the 3min signal fired
  // and he actually got out, swap it for "Cut on Invalidation" — otherwise the
  // comparison quietly leans toward holding.
  const breakdown3m = byText('Did 3min MACD Breakdown?');
  const breakout3m = byText('Did 3min MACD Breakout?');
  if(breakdown3m === 'yes' || breakout3m === 'yes'){
    reasons.add('Held Through Invalidation');
  }

  const crossDown = byText('Did MACD cross the zero line downward when your order triggered?');
  const crossUp = byText('Did MACD cross the zero line upward when your order triggered?');
  if(crossDown === 'no' || crossUp === 'no'){
    reasons.add('Entered Without Confirmation');
    reasons.add('Entered Without Confirmation');
    reasons.add('FOMO Entry');
  }

  // Higher-timeframe bias. The 1 hour setups ask this on the 4H instead of the
  // 1H, so both wordings are checked — a checklist only ever contains one of
  // them, and missing the 4H version left the entire 1 hour setup with no
  // bias rule at all.
  const bear1h = byText('1H MACD in Bear Territory (Red Histogram)?');
  const bull1h = byText('1H MACD in Bull Territory (Green Histogram)?');
  const bear4h = byText('4H MACD in Bear Territory (Red Histogram)?');
  const bull4h = byText('4H MACD in Bull Territory (Green Histogram)?');
  if([bear1h, bull1h, bear4h, bull4h].includes('no')){
    reasons.add('Against Daily Bias / HTF Bias');
  }

  // Divergence. These questions are INVERTED — a hand being present is the
  // warning — so "yes" is the breach, not "no". This had no rule anywhere,
  // including the 5 mins and 15 mins setups where the question has existed
  // all along.
  // A divergence hand being present says the move is running out of strength —
  // that is the "already extended" mistake, not a direction one. It briefly
  // pointed at the HTF bias tag, which was simply wrong.
  const leftHand = byText('Left Hand Present?');
  const rightHand = byText('Right Hand Present?');
  if(leftHand === 'yes' || rightHand === 'yes'){
    reasons.add('Chased Extended Move');
  }

  // Matched on the item being a `select`, not on its wording. The old version
  // listed the four question texts by hand, so renaming one — say from "Which
  // 15m HL is this?" to "Which 1h HL is this?" — would have quietly stopped
  // the rule firing on that setup with nothing to show it had broken.
  // Entering on the 3rd HL/LH onward IS the "already extended" mistake, in his
  // own words: the market has already made its move and he is still expecting
  // another leg. This is the auto-rule that names it most directly.
  const lateSequence = new Set(['3rd','4th','5th']);
  cfg.items.forEach((it, i) => {
    if(it.select && lateSequence.has(answers[i])) reasons.add('Chased Extended Move');
  });

  return reasons;
}

let confluenceTarget = null;  // { type:'setup', id } | { type:'trade', positionId }
let confluenceAnswers = {};   // { itemIndex: 'yes' | 'almost' | 'no' }
let confluenceChartPattern = null;

// Trade Type narrows which Pattern Type options make sense — Long only
// ever trades HL patterns (plus the shared Invalidation Play), Short only
// LH ones (plus the same shared one) — filtering the dropdown down makes
// the right option faster to find instead of scrolling all 9.
function _patternTypesForTradeType(tt){
  if(tt === 'Long') return FIELD_OPTIONS.pattern_type.filter(p => p.includes('HL') || p === '30 mins Invalidation Play');
  if(tt === 'Short') return FIELD_OPTIONS.pattern_type.filter(p => p.includes('LH') || p === '30 mins Invalidation Play');
  return FIELD_OPTIONS.pattern_type;
}

function _confluenceKey(){
  const tt = document.getElementById('confluenceTradeType')?.value;
  const pt = document.getElementById('confluencePatternType')?.value;
  return (tt && pt) ? `${tt}|${pt}` : null;
}

function _renderConfluencePatternOptions(selected){
  const tt = document.getElementById('confluenceTradeType').value;
  const allowed = _patternTypesForTradeType(tt);
  const sel = document.getElementById('confluencePatternType');
  sel.innerHTML = '<option value="">— choose —</option>' +
    allowed.map(o => `<option value="${o}" ${selected===o?'selected':''}>${o}</option>`).join('');
  if(selected && !allowed.includes(selected)) sel.value = '';
}

function openConfluenceModal(id){
  const s = SAVED_SETUPS.find(x => x.id === id);
  if(!s) return;
  confluenceTarget = { type:'setup', id };
  _openConfluenceModalWith(s);
}

// One checklist written to every ticked setup — for the same setup taken
// across several accounts, where the confluence is identical by definition.
function openConfluenceModalBulk(){
  const ids = [...SELECTED_SETUP_IDS];
  if(!ids.length) return;
  const first = SAVED_SETUPS.find(x => x.id === ids[0]);
  if(!first) return;
  confluenceTarget = { type:'setup-bulk', ids };
  // Seed from whichever already has a checklist, so re-opening a partly
  // filled group doesn't start from blank.
  const seed = SAVED_SETUPS.find(x => ids.includes(x.id) && x.pattern_type) || first;
  _openConfluenceModalWith(seed);
}

// Reached from the Trade View modal — lets confluence be filled in (or
// corrected) on a trade that's already journaled, including ones logged
// before this feature existed.
function openConfluenceModalForTrade(positionId){
  const row = RAW_TRADES.find(r => r.position_id === positionId);
  if(!row) return;
  confluenceTarget = { type:'trade', positionId };
  _openConfluenceModalWith(row);
}

function openConfluenceModalFromTradeView(){
  const row = tradeViewList[tradeViewIndex];
  if(row) openConfluenceModalForTrade(row.position_id);
}

function _openConfluenceModalWith(s){
  confluenceAnswers = (s.confluence_answers && typeof s.confluence_answers === 'object') ? {...s.confluence_answers} : {};
  confluenceChartPattern = s.chart_pattern || null;

  document.getElementById('confluenceTradeType').innerHTML =
    '<option value="">— choose —</option>' + FIELD_OPTIONS.trade_type.map(o => `<option value="${o}" ${s.trade_type===o?'selected':''}>${o}</option>`).join('');
  _renderConfluencePatternOptions(s.pattern_type);

  const noteEl = document.getElementById('confluenceBulkNote');
  if(noteEl){
    const bulk = confluenceTarget && confluenceTarget.type === 'setup-bulk';
    noteEl.style.display = bulk ? '' : 'none';
    if(bulk){
      const names = confluenceTarget.ids
        .map(id => SAVED_SETUPS.find(x => x.id === id)?.account_name)
        .filter(Boolean);
      noteEl.textContent = `Applying to ${confluenceTarget.ids.length} setups: ${names.join(', ')}`;
    }
  }

  renderConfluenceChecklist();
  document.getElementById('confluenceModal').classList.add('open');
}

function closeConfluenceModal(){
  document.getElementById('confluenceModal').classList.remove('open');
  confluenceTarget = null;
}

function onConfluenceTradeTypeChange(){
  const currentPattern = document.getElementById('confluencePatternType').value;
  _renderConfluencePatternOptions(currentPattern);
  onConfluenceTypeChange();
}

function onConfluenceTypeChange(){
  // Switching Trade Type/Pattern Type mid-fill would silently keep stale
  // answers from a different checklist shape — start clean instead.
  confluenceAnswers = {};
  confluenceChartPattern = null;
  renderConfluenceChecklist();
}

function renderConfluenceChecklist(){
  const body = document.getElementById('confluenceBody');
  const key = _confluenceKey();
  if(!key){
    body.innerHTML = '<div class="empty-state">Pick a Pattern Type (and Trade Type, if it appears) first.</div>';
    return;
  }
  const cfg = CONFLUENCE_SETUPS[key];
  if(!cfg){
    body.innerHTML = '<div class="empty-state">No confluence checklist configured for this combination yet.</div>';
    return;
  }

  const { total, done, unanswered } = _confluenceProgress(cfg.items, confluenceAnswers, !!confluenceChartPattern);

  const itemsHtml = cfg.items.map((it, i) =>
    _renderConfluenceItemRow(it, i, confluenceAnswers[i], 'setConfluenceAnswer')
  ).join('');

  const chipsHtml = ['None', ..._confluencePatternChoices(cfg, confluenceChartPattern)].map(p => {
    const isActive = (p === 'None' && !confluenceChartPattern) || p === confluenceChartPattern;
    return `<span class="cfl-pattern-chip ${p==='None'?'cfl-none':''} ${isActive?'active':''}" onclick="selectConfluenceChartPattern('${p.replace(/'/g,"\\'")}')">${p}</span>`;
  }).join('');

  body.innerHTML = `
    <div class="cfl-checklist-head">
      <div class="cfl-checklist-title">Confluence Checklist</div>
      <div class="cfl-progress-chip">
        <span class="cfl-progress-track"><span class="cfl-progress-fill" style="width:${total?(done/total*100):0}%;"></span></span>
        <span class="num">${Number(done.toFixed(1))}/${total}</span>
      </div>
    </div>
    ${unanswered > 0 ? `<div class="cfl-unanswered-note">${unanswered} question${unanswered===1?'':'s'} not yet answered</div>` : ''}
    <div class="cfl-checklist-card">${itemsHtml}</div>
    <div class="cfl-pattern-picker">
      <div class="cfl-pattern-picker-head">
        <span class="cfl-pattern-picker-title">Chart Pattern</span>
      </div>
      <div class="cfl-pattern-chips">${chipsHtml}</div>
    </div>
    ${_bbWarningSignsHtml(key, cfg, done, total, confluenceAnswers)}
  `;
}

function setConfluenceAnswer(i, val){
  confluenceAnswers[i] = (confluenceAnswers[i] === val) ? undefined : val;
  if(confluenceAnswers[i] === undefined) delete confluenceAnswers[i];
  const cfg = CONFLUENCE_SETUPS[_confluenceKey()];
  if(cfg) _applyConfluenceImplications(cfg.items, confluenceAnswers, i);
  renderConfluenceChecklist();
}

function selectConfluenceChartPattern(p){
  confluenceChartPattern = (p === 'None') ? null : p;
  renderConfluenceChecklist();
}

async function saveConfluenceModal(){
  if(!confluenceTarget) return;
  const tradeType = document.getElementById('confluenceTradeType').value || null;
  const patternType = document.getElementById('confluencePatternType').value || null;
  const payload = {
    trade_type: tradeType,
    pattern_type: patternType,
    confluence_answers: confluenceAnswers,
    chart_pattern: confluenceChartPattern
  };

  // Auto-populate Rules Followed / Unfollowed Rules from the checklist just
  // answered — only for an already-journaled trade (Pending Setups have no
  // rules_followed/unfollowed_rules columns), and only additive: a clean
  // checklist never resets an existing "No" back to blank.
  if(confluenceTarget.type === 'trade' && tradeType && patternType){
    const cfg = CONFLUENCE_SETUPS[`${tradeType}|${patternType}`];
    if(cfg){
      const autoReasons = _autoUnfollowedRules(cfg, confluenceAnswers, !!confluenceChartPattern);
      if(autoReasons.size){
        const existingRow = RAW_TRADES.find(r => r.position_id === confluenceTarget.positionId);
        const existing = (existingRow?.unfollowed_rules || '').split(/[,;]/).map(s => s.trim()).filter(Boolean);
        const merged = [...new Set([...existing, ...autoReasons])];
        payload.rules_followed = 'No';
        payload.unfollowed_rules = merged.join(', ');
      }
    }
  }

  try{
    if(confluenceTarget.type === 'setup-bulk'){
      // PostgREST in.() so all the ticked setups are written in one request —
      // no partial state if the connection drops halfway through.
      const idList = confluenceTarget.ids.join(',');
      const res = await fetch(`${SUPABASE_URL}/rest/v1/position_setups?id=in.(${idList})`, {
        method: 'PATCH',
        headers: {
          "apikey": SUPABASE_KEY, "Authorization": `Bearer ${USER_ACCESS_TOKEN}`,
          "Content-Type": "application/json", "Prefer": "return=representation"
        },
        body: JSON.stringify(payload)
      });
      if(!res.ok) throw new Error(await res.text());
      const updated = await res.json();
      updated.forEach(u => {
        const idx = SAVED_SETUPS.findIndex(s => s.id === u.id);
        if(idx !== -1) SAVED_SETUPS[idx] = u;
      });
      clearSetupSelection();
      closeConfluenceModal();
      showToast(`Confluence saved to ${updated.length} setup${updated.length===1?'':'s'}`);
      return;
    }
    if(confluenceTarget.type === 'setup'){
      const res = await fetch(`${SUPABASE_URL}/rest/v1/position_setups?id=eq.${confluenceTarget.id}`, {
        method: 'PATCH',
        headers: {
          "apikey": SUPABASE_KEY, "Authorization": `Bearer ${USER_ACCESS_TOKEN}`,
          "Content-Type": "application/json", "Prefer": "return=representation"
        },
        body: JSON.stringify(payload)
      });
      if(!res.ok) throw new Error(await res.text());
      const updated = await res.json();
      const idx = SAVED_SETUPS.findIndex(s => s.id === confluenceTarget.id);
      if(idx !== -1 && updated[0]) SAVED_SETUPS[idx] = updated[0];
      renderSavedSetups();
    }else{
      const res = await fetch(`${SUPABASE_URL}/rest/v1/${TABLE_NAME}?position_id=eq.${encodeURIComponent(confluenceTarget.positionId)}`, {
        method: 'PATCH',
        headers: {
          "apikey": SUPABASE_KEY, "Authorization": `Bearer ${USER_ACCESS_TOKEN}`,
          "Content-Type": "application/json", "Prefer": "return=representation"
        },
        body: JSON.stringify(payload)
      });
      if(!res.ok) throw new Error(await res.text());
      const updated = await res.json();
      const idx = RAW_TRADES.findIndex(r => r.position_id === confluenceTarget.positionId);
      if(idx !== -1 && updated[0]) RAW_TRADES[idx] = updated[0];
      renderJournalTable();
      if(document.getElementById('tradeViewModal').classList.contains('open')) renderTradeViewModal();
    }
    closeConfluenceModal();
    showToast('Confluence saved');
  }catch(e){
    console.error("Couldn't save confluence:", e);
    await customAlert("Couldn't save — make sure you've run supabase_confluence.sql in Supabase.");
  }
}

// Same setup taken across several accounts shares one confluence — these
// let you tick those rows and fill the checklist once instead of repeating
// it per account.
let SELECTED_SETUP_IDS = new Set();

function toggleSetupSelect(id, checked){
  if(checked) SELECTED_SETUP_IDS.add(id); else SELECTED_SETUP_IDS.delete(id);
  renderSetupBulkBar();
}

function toggleAllSetupSelection(checked){
  const pending = SAVED_SETUPS.filter(s => (s.status || 'Pending') !== 'Journaled');
  SELECTED_SETUP_IDS = checked ? new Set(pending.map(s => s.id)) : new Set();
  renderSavedSetups();
}

function clearSetupSelection(){
  SELECTED_SETUP_IDS = new Set();
  renderSavedSetups();
}

function renderSetupBulkBar(){
  const bar = document.getElementById('setupBulkBar');
  const count = document.getElementById('setupBulkCount');
  if(!bar || !count) return;
  const n = SELECTED_SETUP_IDS.size;
  bar.style.display = n ? 'flex' : 'none';
  count.textContent = `${n} setup${n===1?'':'s'} selected`;
}

// Confluence can be written to every ticked setup at once because it really
// is identical across accounts. A journal can't: the realized P&L and the fee
// on each order ticket are that account's own numbers, and nothing on another
// account's card can produce them. So this walks the ticked setups one at a
// time, naming the account it's waiting on, instead of writing them together.
let journalQueue = [];        // setup ids still to journal; [0] is the current one
let journalQueueTotal = 0;    // fixed at the start, for the "x of y" counter
// Each account's pasted ticket, banked while the run collects them. Emptied
// when the single drawer at the end is saved or abandoned.
let journalBulkPastes = [];

// Everything that differs per account and is already known — from the ticket
// just pasted or from the setup itself. Hidden in the bulk drawer, because
// there is no single value for them and filling one in for all three would be
// wrong by definition, not merely unhelpful.
// Shown in the drawer as read-only computed text, never as inputs — they are
// worked out from other fields at display time and have no column on the
// journal table. _collectDrawerPatch never returns them because it only reads
// inputs, so a single trade is safe by accident. A bulk row is assembled from
// the setup prefill as well as the form, so they have to be stripped on
// purpose: PostgREST rejects the WHOLE batch over one unknown column, not just
// that field, so a stray key here means nothing gets journaled at all.
const JOURNAL_COMPUTED_KEYS = new Set(['objective', 'duration', 'risk_amount', 'trade_summary']);

const BULK_HIDDEN_KEYS = new Set([
  'account','account_type','position_size','risk_amount','quantity',
  'tp_price','sl_price','entry_price','close_price',
  'profit_loss','pnl_percent','fee','rr','win_loss',
  'symbol','open_date','close_date','duration','day_of_week',
  'trade_type'
  // pattern_type is deliberately NOT hidden. It arrives from the Setup, but
  // the wrong one does get picked there, and this is the last point before
  // three rows are written with it.
]);
async function journalSelectedSetups(){
  const pending = SAVED_SETUPS.filter(s => (s.status || 'Pending') !== 'Journaled');
  const picked = pending.filter(s => SELECTED_SETUP_IDS.has(s.id));
  if(!picked.length) return;

  // Same gate as the per-row Journal button, which sits disabled until a
  // confluence exists — enforced again here so ticking a row can't route
  // around it.
  const ready = picked.filter(s => s.pattern_type);
  const missing = picked.filter(s => !s.pattern_type);
  if(!ready.length){
    await customAlert('Fill in Confluence first — none of the selected setups have one yet.');
    return;
  }
  if(missing.length){
    const names = missing.map(s => s.account_name || 'unnamed').join(', ');
    // customConfirm writes with textContent and defaults its OK button to
    // "Delete", so: one flowing line, and an explicit label.
    const ok = await customConfirm(
      `${missing.length} selected setup${missing.length===1?' has':'s have'} no Confluence yet (${names}) and will be skipped. Journal the other ${ready.length}?`,
      `Journal ${ready.length}`
    );
    if(!ok) return;
  }

  journalQueue = ready.map(s => s.id);
  journalQueueTotal = journalQueue.length;
  journalBulkPastes = [];
  journalFromSetup(journalQueue[0]);
}

// One insert for the whole run, then the follow-up work each row needs. Rows
// go up together so a dropped connection can't leave two of three trades
// saved with no sign that the third is missing.
async function _saveBulkJournal(shared){
  const { rows, confluenceDropped } = _bulkJournalRows(shared);
  const setupIds = drawerBulkTargets.map(t => t.setupId);

  const res = await fetch(`${SUPABASE_URL}/rest/v1/${TABLE_NAME}`, {
    method: 'POST',
    headers: {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${USER_ACCESS_TOKEN}`,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation'
    },
    body: JSON.stringify(rows)
  });
  if(!res.ok) throw new Error(await res.text());
  const inserted = await res.json();
  (inserted.length ? inserted : rows).forEach(r => RAW_TRADES.push(r));

  ALL_TRADES = RAW_TRADES.map(normalizeTrade);
  _rebuildTradeNumbers();
  populateAccountFilter();
  populateDashPeriodFilters();
  populateJournalFilters();
  applyFilters();
  renderJournalTable();
  refreshAllNavBadges();

  // Each account moves by its own net, so these are separate adjustments even
  // when every row came from the same setup.
  for(const r of rows){
    if(!r.account) continue;
    await adjustAccountBalance(r.account, (parseFloat(r.profit_loss) || 0) - (parseFloat(r.fee) || 0));
  }
  await Promise.all(setupIds.map(id => setSetupStatus(id, 'Journaled')));

  const n = rows.length;
  _cancelJournalQueue();
  clearSetupSelection();
  loadLinkedSetupScreenshots().then(renderJournalTable);
  closeDrawer();
  showToast(confluenceDropped
    ? `Journaled ${n} trade${n===1?'':'s'} — confluence cleared on ${confluenceDropped}, pattern type changed. Re-run it from the trade.`
    : `Journaled ${n} trade${n===1?'':'s'}`);
}

function _cancelJournalQueue(){
  journalQueue = [];
  journalQueueTotal = 0;
  journalBulkPastes = [];
  drawerBulkTargets = null;
}

// Every ticket is in. One drawer now, seeded from the first one so the
// auto-filled values are there to save, but rendering only the fields that
// still need an answer — not repeating those is the whole point of the run.
function _openBulkJournalDrawer(){
  if(!journalBulkPastes.length) return;
  drawerBulkTargets = journalBulkPastes.slice();
  openDrawer('create', null, { ...drawerBulkTargets[0].parsed });
}

function _bulkNoteTargets(){
  const pending = SAVED_SETUPS.filter(s => (s.status || 'Pending') !== 'Journaled');
  return pending.filter(s => SELECTED_SETUP_IDS.has(s.id));
}

function openBulkNotesModal(){
  const targets = _bulkNoteTargets();
  if(!targets.length) return;
  document.getElementById('bulkNotesEntry').value = '';
  document.getElementById('bulkNotesError').textContent = '';
  document.getElementById('bulkNotesCount').textContent =
    `Goes to ${targets.length} setup${targets.length===1?'':'s'}:`;
  document.getElementById('bulkNotesTargets').innerHTML = targets
    .map(s => `<span class="bulk-note-chip">${escapeHtml(s.account_name || 'No account')}</span>`)
    .join('');
  document.getElementById('bulkNotesModal').classList.add('open');
  document.getElementById('bulkNotesEntry').focus();
}

function closeBulkNotesModal(){
  document.getElementById('bulkNotesModal').classList.remove('open');
}

// One note appended to every ticked setup. Unlike the confluence bulk write
// this can't be a single request: each setup's notes_log is its own array, so
// there's no one payload that fits them all. An upsert would have collapsed it
// into one call, but position_setups.id is `generated always as identity` and
// leverage is NOT NULL — Postgres rejects that INSERT tuple before it ever
// reaches the ON CONFLICT clause. So: one PATCH each, fired together.
async function saveBulkNotes(){
  const errEl = document.getElementById('bulkNotesError');
  const btn = document.getElementById('bulkNotesSaveBtn');
  errEl.textContent = '';

  const text = document.getElementById('bulkNotesEntry').value.trim();
  if(!text){ errEl.textContent = 'Write the note first.'; return; }

  const targets = _bulkNoteTargets();
  if(!targets.length){
    errEl.textContent = 'Nothing is selected any more — close this and tick some setups.';
    return;
  }

  btn.disabled = true;
  btn.textContent = 'Saving…';
  // One timestamp for the whole batch, so the same note reads as a single
  // moment across every account instead of drifting by however long the
  // requests happened to take.
  const entry = { ts: new Date().toISOString(), text };

  try{
    const results = await Promise.all(targets.map(async s => {
      const log = [...(Array.isArray(s.notes_log) ? s.notes_log : []), entry];
      try{
        const res = await fetch(`${SUPABASE_URL}/rest/v1/position_setups?id=eq.${s.id}`, {
          method: 'PATCH',
          headers: {
            "apikey": SUPABASE_KEY, "Authorization": `Bearer ${USER_ACCESS_TOKEN}`,
            "Content-Type": "application/json", "Prefer": "return=representation"
          },
          body: JSON.stringify({ notes_log: log })
        });
        if(!res.ok) return { s, ok:false };
        const rows = await res.json();
        return rows.length ? { s, ok:true, log } : { s, ok:false };
      }catch(e){
        return { s, ok:false };
      }
    }));

    // Local state moves only for the ones that actually landed — a partial
    // failure must not leave the table showing a note the database refused.
    results.filter(r => r.ok).forEach(r => { r.s.notes_log = r.log; });
    const failed = results.filter(r => !r.ok);

    if(failed.length){
      const names = failed.map(r => r.s.account_name || 'unnamed').join(', ');
      errEl.textContent = `Saved to ${results.length - failed.length} of ${results.length}. Failed: ${names}. If this keeps happening, run supabase_position_setups_add_update_policy.sql in Supabase.`;
      renderSavedSetups();
      return;
    }

    closeBulkNotesModal();
    clearSetupSelection();
    showToast(`Note added to ${results.length} setup${results.length===1?'':'s'}`);
  }catch(e){
    console.error("Couldn't save bulk notes:", e);
    errEl.textContent = "Couldn't save — " + e.message;
  }finally{
    btn.disabled = false;
    btn.textContent = 'Add note';
  }
}

// Called once a queued trade has actually saved — drops the head and opens
// the next account's paste box. Guarded on the head matching so an unrelated
// save can never advance someone else's run.
// Builds one journal row per pasted ticket: that account's own numbers, plus
// the answers given once in the drawer. Anything left blank in the drawer is
// dropped rather than written, so an unanswered field can't wipe a value the
// ticket already supplied.
function _bulkJournalRows(shared){
  const answered = Object.fromEntries(
    Object.entries(shared).filter(([, v]) => v !== null && v !== '')
  );
  const maxNo = RAW_TRADES.reduce((m, r) => {
    const n = parseFloat(r.no);
    return !isNaN(n) && n > m ? n : m;
  }, 0);
  let confluenceDropped = 0;

  const rows = drawerBulkTargets.map((t, i) => {
    const patch = { ...t.parsed, ...answered };
    patch.no = maxNo + 1 + i;
    // Index in the id so three rows created in the same millisecond can't
    // collide on the position_id.
    patch.position_id = 'WEB-' + Date.now().toString(36).toUpperCase() + '-' + (i + 1);
    patch.linked_setup_id = t.setupId;

    const setup = SAVED_SETUPS.find(s => s.id === t.setupId);
    if(setup){
      // Confluence answers are stored by their position in that pattern's
      // checklist. Correcting the Pattern Type here means a different
      // checklist, so those answers would now point at different questions —
      // carrying them would produce confidently wrong data. Dropped instead,
      // and said out loud rather than silently.
      const patternChanged = patch.pattern_type && setup.pattern_type
        && patch.pattern_type !== setup.pattern_type;
      if(patternChanged){
        if(setup.confluence_answers || setup.chart_pattern) confluenceDropped++;
      }else{
        // Filled in on the Setup itself and never rendered in the drawer, so
        // it has to be carried across explicitly or it is simply lost.
        if(setup.confluence_answers) patch.confluence_answers = setup.confluence_answers;
        if(setup.chart_pattern) patch.chart_pattern = setup.chart_pattern;
      }
    }

    // Derived here rather than in the drawer, because the field it would
    // normally be written into isn't rendered in a bulk run — and it differs
    // per account anyway, since each one has its own phase.
    if(!patch.account_type && patch.account){
      const accType = _accountTypeFor(patch.account);
      if(accType) patch.account_type = accType;
    }

    // Trade Type is a BULK_HIDDEN_KEY, so its change event never fires here and
    // the Trade Setup cascade the drawer relies on never runs. Repeat it.
    if(!patch.trade_setup && patch.trade_type){
      const mappedSetup = TRADE_TYPE_SETUP_MAP[patch.trade_type];
      if(mappedSetup) patch.trade_setup = mappedSetup;
    }
    if(patch.trade_setup === 'Invalidation Play'){
      if(!patch.pattern_type) patch.pattern_type = '30 mins Invalidation Play';
      if(!patch.aof_phase) patch.aof_phase = 'Invalidation';
    }
    if(!patch.execution_tf){
      const mappedTf = _execTfFor(patch.pattern_type);
      if(mappedTf) patch.execution_tf = mappedTf;
    }
    // Per row, not once for the batch: the Sequence answer lives on each row's
    // OWN setup, so three accounts sharing one drawer can still land on
    // different AOF Phases. Uses the answers merged just above.
    if(!patch.aof_phase){
      const mappedAof = PATTERN_FIXED_AOF[patch.pattern_type]
        || _aofFromSequence(patch.trade_type, patch.pattern_type, patch.confluence_answers);
      if(mappedAof) patch.aof_phase = mappedAof;
    }

    // Per row, not once for the batch: exit type and a moved stop are both
    // read off that account's own prices.
    if(patch.exit_type == null){
      const auto = _autoExitType(patch);
      if(auto) patch.exit_type = auto;
    }
    _applyMovedStopFlags(patch);
    // Also per row, because the Exit Type it depends on was just decided per
    // row above. Same rule as the single-trade path: settle everything that is
    // not a cut, leave a real cut blank so the journal asks for it.
    if(!patch.post_cutloss_result && patch.exit_type &&
       String(patch.exit_type).trim().toLowerCase() !== 'cut loss'){
      patch.post_cutloss_result = 'N/A';
    }
    JOURNAL_COMPUTED_KEYS.forEach(k => delete patch[k]);
    return patch;
  });

  return { rows, confluenceDropped };
}

// Leverage tint: the higher the leverage, the tighter the margin and the
// less room the position has — green through red across 1x-5x, clamped
// beyond that.
function _leverageTint(lev){
  const l = Number(lev);
  if(!(l > 0)) return 'var(--ink)';
  if(l <= 1) return 'var(--win)';
  if(l <= 2) return 'color-mix(in srgb, var(--win) 60%, var(--warn))';
  if(l <= 3) return 'var(--warn)';
  if(l <= 4) return 'color-mix(in srgb, var(--loss) 60%, var(--warn))';
  return 'var(--loss)';
}

function setupRowHTML(s, selectable){
  const riskAmount = Number(s.risk_amount);
  // Prices/quantity only exist on setups saved after the calculator became
  // price-driven — older rows (percentage era) simply show "—" for them.
  // Shown and copied at 2 decimals: cent precision is all an order form
  // needs, and Copy hands over the bare number (no thousands separators)
  // so it pastes straight into the exchange.
  const priceCell = (v, color) => v == null ? '—' : `
    <span style="color:${color};">${Number(v).toFixed(2)}</span>
    <button class="poscalc-copy-btn" title="Copy price" onclick="event.stopPropagation(); copyPriceToClipboard('${Number(v).toFixed(2)}', this)">${copyIconSVG()}</button>`;
  const status = s.status || 'Pending';
  const statusPillClass = setupStatusPillClass(status);
  return `
  <tr onclick="openSetupNotesModal(${s.id})" style="cursor:pointer;">
    ${selectable ? `<td onclick="event.stopPropagation();"><input type="checkbox" ${SELECTED_SETUP_IDS.has(s.id) ? 'checked' : ''} onclick="toggleSetupSelect(${s.id}, this.checked)"></td>` : ''}
    <td>${escapeHtml(s.symbol || '—')}</td>
    <td>${new Date(s.created_at).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'})}</td>
    <td>${escapeHtml(s.account_name || '—')}</td>
    <td style="color:${_leverageTint(s.leverage)};font-weight:700;">${s.leverage}x</td>
    <td>$${riskAmount.toLocaleString(undefined,{maximumFractionDigits:2})}</td>
    <td>${s.quantity != null ? Number(s.quantity).toFixed(4) : '—'}</td>
    <td style="white-space:nowrap;">${priceCell(s.entry_price, 'var(--accent)')}</td>
    <td style="white-space:nowrap;">${priceCell(s.tp_price, 'var(--win)')}</td>
    <td style="white-space:nowrap;">${priceCell(s.sl_price, 'var(--loss)')}</td>
    <td><span class="pill ${statusPillClass}">${escapeHtml(status)}</span></td>
    <td style="white-space:nowrap;">
      <button class="poscalc-accent-btn" onclick="event.stopPropagation(); openConfluenceModal(${s.id})">${s.pattern_type ? 'Edit Confluence' : 'Confluence'}</button>
      ${status !== 'Journaled'
        ? `<button class="poscalc-accent-btn" ${!s.pattern_type ? 'disabled title="Fill in Confluence first"' : ''} onclick="event.stopPropagation(); journalFromSetup(${s.id})">Journal</button>`
        : `<button class="poscalc-accent-btn" onclick="event.stopPropagation(); setSetupStatus(${s.id}, 'Pending')">Revert to Pending</button>`}
      <button class="drawer-danger-btn" onclick="event.stopPropagation(); deleteSavedSetup(${s.id})">Delete</button>
    </td>
  </tr>
`;
}

/* ---------------- Journaled Setups: itago / ipakita ----------------
   Ang listahang ito ay tinitingnan minsan lang — pagkatapos i-journal ang isang
   setup — pero nasa ilalim ito ng Calculator araw-araw. Kaya isang lid.

   Nananatiling NAKIKITA ang default. Ang pagtatago nito nang kusa ay magmumukhang
   nawala ang panel; ang pagpindot minsan ay isang desisyon na naaalala.
   Ang bilang ay nananatili sa buton kahit nakatipi, kaya hindi nawawala ang
   impormasyon — nawawala lang ang laki nito. */
function _journaledSetupsHidden(){
  try{ return localStorage.getItem('ledger-journaled-setups-hidden') === '1'; }
  catch(e){ return false; }
}

function applyJournaledSetupsFold(count){
  const wrap = document.getElementById('journaledSetupsWrap');
  const btn  = document.getElementById('journaledSetupsFoldBtn');
  if(!wrap || !btn) return;
  const hidden = _journaledSetupsHidden();
  wrap.style.display = hidden ? 'none' : '';
  // Ang bilang ay opsyonal: kapag tinawag ito nang wala nito (halimbawa sa
  // unang laglag bago dumating ang setups), ang nasa DOM na ang sinasagot.
  const n = (count === undefined)
    ? document.querySelectorAll('#journaledSetupsBody tr').length
    : count;
  btn.textContent = (hidden ? 'Show' : 'Hide') + (n ? ` (${n})` : '');
  btn.setAttribute('aria-expanded', hidden ? 'false' : 'true');
  btn.title = hidden ? 'Show the journaled setups' : 'Hide this list — the count stays here';
}

function toggleJournaledSetups(){
  try{ localStorage.setItem('ledger-journaled-setups-hidden',
       _journaledSetupsHidden() ? '0' : '1'); }catch(e){}
  applyJournaledSetupsFold();
  syncUIPrefsToProfile();
}

function renderSavedSetups(){
  const pendingTable = document.getElementById('pendingSetupsTable');
  const pendingBody = document.getElementById('pendingSetupsBody');
  const pendingEmptyState = document.getElementById('pendingSetupsEmptyState');
  const journaledTable = document.getElementById('journaledSetupsTable');
  const journaledBody = document.getElementById('journaledSetupsBody');
  const journaledEmptyState = document.getElementById('journaledSetupsEmptyState');
  if(!pendingTable || !pendingBody || !journaledTable || !journaledBody) return;

  const pending = SAVED_SETUPS.filter(s => (s.status || 'Pending') !== 'Journaled');
  const journaled = SAVED_SETUPS.filter(s => s.status === 'Journaled');

  // Drop selections for setups that no longer exist (deleted or journaled)
  // so the bulk bar can never act on a stale id.
  const pendingIds = new Set(pending.map(s => s.id));
  SELECTED_SETUP_IDS.forEach(id => { if(!pendingIds.has(id)) SELECTED_SETUP_IDS.delete(id); });

  if(pending.length){
    pendingEmptyState.style.display = 'none';
    pendingTable.style.display = '';
    pendingBody.innerHTML = pending.map(s => setupRowHTML(s, true)).join('');
  }else{
    pendingEmptyState.style.display = 'block';
    pendingTable.style.display = 'none';
  }

  const selectAll = document.getElementById('setupSelectAll');
  if(selectAll) selectAll.checked = pending.length > 0 && SELECTED_SETUP_IDS.size === pending.length;
  renderSetupBulkBar();

  if(journaled.length){
    journaledEmptyState.style.display = 'none';
    journaledTable.style.display = '';
    journaledBody.innerHTML = journaled.map(s => setupRowHTML(s, false)).join('');
  }else{
    journaledEmptyState.style.display = 'block';
    journaledTable.style.display = 'none';
  }
  // Ang bilang ay nasa buton, kaya may masasabi pa rin ito kahit nakatago:
  // "Show (7)" ay sapat na para malaman kung may dapat bang tingnan.
  applyJournaledSetupsFold(journaled.length);
}

// Before/After are two fixed, independent slots (not a growing log) — each
// pasted image replaces whatever was in that slot. Uploaded to storage only
// on Save, so cancelling out of the modal costs nothing.
let activeScreenshotSlot = 'before';
let pendingScreenshotBlobs = { before: null, after: null };
let removedScreenshotSlots = { before: false, after: false };

function setActiveScreenshotSlot(slot){
  activeScreenshotSlot = slot;
}

// Second way in besides Ctrl+V — opens the OS file/photo picker (gallery,
// camera roll, or "Take Photo" on mobile) for whichever slot was clicked.
function triggerScreenshotFilePicker(slot){
  activeScreenshotSlot = slot;
  document.getElementById(slot === 'before' ? 'setupNotesBeforeFileInput' : 'setupNotesAfterFileInput').click();
}

function handleScreenshotFileSelect(slot, inputEl){
  const file = inputEl.files[0];
  if(!file) return;
  pendingScreenshotBlobs[slot] = file;
  removedScreenshotSlots[slot] = false;
  renderScreenshotSlotPreview(slot, URL.createObjectURL(file));
  inputEl.value = ''; // allow picking the same file again later (e.g. after Remove)
}

function _screenshotZoneId(slot){
  return slot === 'before' ? 'setupNotesBeforeDropzone' : 'setupNotesAfterDropzone';
}

document.addEventListener('paste', (e) => {
  const modal = document.getElementById('setupNotesModal');
  if(!modal || !modal.classList.contains('open')) return;
  const items = e.clipboardData && e.clipboardData.items;
  if(!items) return;
  for(const item of items){
    if(item.type && item.type.startsWith('image/')){
      const blob = item.getAsFile();
      if(!blob) continue;
      pendingScreenshotBlobs[activeScreenshotSlot] = blob;
      removedScreenshotSlots[activeScreenshotSlot] = false;
      renderScreenshotSlotPreview(activeScreenshotSlot, URL.createObjectURL(blob));
      e.preventDefault();
      break;
    }
  }
});

function renderScreenshotSlotPreview(slot, url){
  const zone = document.getElementById(_screenshotZoneId(slot));
  if(!zone) return;
  zone.innerHTML = `
    <img src="${url}" onclick="event.stopPropagation(); openLightbox('${url}')">
    <button class="poscalc-copy-btn" title="Remove" onclick="event.stopPropagation(); removeScreenshotSlot('${slot}')">✕</button>
  `;
}

function removeScreenshotSlot(slot){
  pendingScreenshotBlobs[slot] = null;
  removedScreenshotSlots[slot] = true;
  const zone = document.getElementById(_screenshotZoneId(slot));
  if(zone) zone.innerHTML = 'Click, then paste (Ctrl+V)';
}

function resetScreenshotSlots(){
  activeScreenshotSlot = 'before';
  pendingScreenshotBlobs = { before: null, after: null };
  removedScreenshotSlots = { before: false, after: false };
}

async function loadScreenshotSlotsIntoModal(s){
  for(const slot of ['before','after']){
    const path = s[`${slot}_screenshot`];
    const zone = document.getElementById(_screenshotZoneId(slot));
    if(!zone) continue;
    if(path){
      try{
        const { data } = await sb.storage.from('setup-screenshots').createSignedUrl(path, 3600);
        if(data && data.signedUrl) renderScreenshotSlotPreview(slot, data.signedUrl);
        else zone.innerHTML = 'Click, then paste (Ctrl+V)';
      }catch(e){
        console.error(`Couldn't load ${slot} screenshot:`, e);
        zone.innerHTML = 'Click, then paste (Ctrl+V)';
      }
    }else{
      zone.innerHTML = 'Click, then paste (Ctrl+V)';
    }
  }
}

async function uploadSetupScreenshot(blob, setupId, slot){
  const { data: { user } } = await sb.auth.getUser();
  const ext = (blob.type && blob.type.split('/')[1]) || 'png';
  const path = `${user.id}/setup_${setupId}_${slot}_${Date.now()}.${ext}`;
  const { error } = await sb.storage.from('setup-screenshots').upload(path, blob, { contentType: blob.type || 'image/png' });
  if(error) throw error;
  return path;
}

async function openSetupNotesModal(id){
  let s = SAVED_SETUPS.find(x => x.id === id);
  if(!s){
    // Opened from the Trade Journal side, where SAVED_SETUPS may never have
    // been loaded — fetch this one row directly instead of requiring a
    // detour through the Calculator view first.
    try{
      const res = await fetch(`${SUPABASE_URL}/rest/v1/position_setups?id=eq.${id}&select=*`, {
        headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${USER_ACCESS_TOKEN}` }
      });
      if(!res.ok) throw new Error(await res.text());
      const rows = await res.json();
      s = rows[0];
      if(s) SAVED_SETUPS.push(s);
    }catch(e){
      console.error("Couldn't load setup:", e);
    }
  }
  if(!s) return;
  editingSetupNotesId = id;
  resetScreenshotSlots();
  document.getElementById('setupNotesSymbol').value = s.symbol || '';
  document.getElementById('setupNotesNewEntry').value = '';
  renderSetupNotesLog(s.notes_log || []);
  loadScreenshotSlotsIntoModal(s);
  document.getElementById('setupNotesModal').classList.add('open');
}

function closeSetupNotesModal(){
  document.getElementById('setupNotesModal').classList.remove('open');
  editingSetupNotesId = null;
  resetScreenshotSlots();
}

function renderSetupNotesLog(log){
  const el = document.getElementById('setupNotesLog');
  if(!log.length){
    el.innerHTML = '<div style="color:var(--muted);font-size:13px;">No notes yet.</div>';
    return;
  }
  el.innerHTML = log.map(entry => `
    <div style="margin-bottom:10px;">
      <div style="font-size:11px;color:var(--muted);font-family:'IBM Plex Mono',monospace;">${new Date(entry.ts).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'})}</div>
      <div style="font-size:13px;color:var(--ink);white-space:pre-wrap;">${escapeHtml(String(entry.text || '').trim())}</div>
    </div>
  `).join('');
}

// Appends a timestamped entry instead of overwriting one blob of text, so
// each update while the trade is open keeps its own datetime.
async function saveSetupNotes(){
  try{
    if(!editingSetupNotesId){ await customAlert("No setup is open — close this and click a saved setup row first."); return; }
    const s = SAVED_SETUPS.find(x => x.id === editingSetupNotesId);
    if(!s){ await customAlert("Couldn't find that saved setup — try reopening it."); return; }

    const symbol = document.getElementById('setupNotesSymbol').value.trim() || null;
    const newText = document.getElementById('setupNotesNewEntry').value.trim();
    const hasScreenshotChange = pendingScreenshotBlobs.before || pendingScreenshotBlobs.after
      || removedScreenshotSlots.before || removedScreenshotSlots.after;
    if(!newText && !hasScreenshotChange && symbol === (s.symbol || null)){
      await customAlert('Nothing to save — enter a Symbol, write a New Note, or paste a screenshot first.');
      return;
    }
    const log = Array.isArray(s.notes_log) ? [...s.notes_log] : [];
    if(newText) log.push({ ts: new Date().toISOString(), text: newText });

    const patch = { symbol, notes_log: log };
    for(const slot of ['before','after']){
      if(pendingScreenshotBlobs[slot]){
        patch[`${slot}_screenshot`] = await uploadSetupScreenshot(pendingScreenshotBlobs[slot], editingSetupNotesId, slot);
      }else if(removedScreenshotSlots[slot]){
        patch[`${slot}_screenshot`] = null;
      }
    }

    const res = await fetch(`${SUPABASE_URL}/rest/v1/position_setups?id=eq.${editingSetupNotesId}`, {
      method: 'PATCH',
      headers: {
        "apikey": SUPABASE_KEY,
        "Authorization": `Bearer ${USER_ACCESS_TOKEN}`,
        "Content-Type": "application/json",
        "Prefer": "return=representation"
      },
      body: JSON.stringify(patch)
    });
    if(!res.ok) throw new Error(await res.text());
    const rows = await res.json();
    if(!rows.length){
      throw new Error("Nothing actually updated in the database (0 rows) — the UPDATE policy on position_setups is probably missing. Run supabase_position_setups_add_update_policy.sql in Supabase.");
    }

    // Update local state directly instead of round-tripping through a
    // reload — shows the new entry immediately, no dependence on refetch timing.
    Object.assign(s, patch);
    document.getElementById('setupNotesNewEntry').value = '';
    resetScreenshotSlots();
    renderSetupNotesLog(log);
    renderSavedSetups();
  }catch(e){
    console.error("Couldn't save setup notes:", e);
    await customAlert("Couldn't save: " + e.message);
  }
}

// Opens the same Setup Notes modal from a Trade Journal entry that was
// created via "Journal" — same underlying position_setups row either way,
// so edits made here show up back in the Calculator too.
function openLinkedSetupNotes(){
  if(!drawerRowData || !drawerRowData.linked_setup_id) return;
  openSetupNotesModal(drawerRowData.linked_setup_id);
}
function openLinkedSetupNotesFromTradeView(){
  const row = tradeViewList[tradeViewIndex];
  if(!row || !row.linked_setup_id) return;
  openSetupNotesModal(row.linked_setup_id);
}

/* ---- Trade Notes (quick timestamped log directly on a trade — no Edit needed) ---- */
let editingTradeNotePositionId = null;

function openTradeNoteModalFromTradeView(){
  const row = tradeViewList[tradeViewIndex];
  if(!row) return;
  openTradeNoteModal(row.position_id);
}

function openTradeNoteModal(positionId){
  const row = RAW_TRADES.find(t => t.position_id === positionId);
  if(!row) return;
  editingTradeNotePositionId = positionId;
  document.getElementById('tradeNoteModalTitle').textContent = `Notes — ${row.symbol || 'Trade'}`;
  document.getElementById('tradeNoteNewEntry').value = '';
  document.getElementById('tradeNoteError').textContent = '';
  renderTradeNoteLog(row.notes_log || []);
  document.getElementById('tradeNoteModal').classList.add('open');
}

function closeTradeNoteModal(){
  document.getElementById('tradeNoteModal').classList.remove('open');
  editingTradeNotePositionId = null;
}

function renderTradeNoteLog(log){
  const el = document.getElementById('tradeNoteLog');
  if(!log.length){
    el.innerHTML = '<div style="color:var(--muted);font-size:13px;">No notes yet.</div>';
    return;
  }
  el.innerHTML = log.map(entry => `
    <div style="margin-bottom:10px;">
      <div style="font-size:11px;color:var(--muted);font-family:'IBM Plex Mono',monospace;">${new Date(entry.ts).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'})}</div>
      <div style="font-size:13px;color:var(--ink);white-space:pre-wrap;">${escapeHtml(String(entry.text || '').trim())}</div>
    </div>
  `).join('');
}

async function saveTradeNote(){
  const errEl = document.getElementById('tradeNoteError');
  errEl.textContent = '';
  if(!editingTradeNotePositionId) return;
  const text = document.getElementById('tradeNoteNewEntry').value.trim();
  if(!text){ errEl.textContent = 'Write something first.'; return; }

  const row = RAW_TRADES.find(t => t.position_id === editingTradeNotePositionId);
  if(!row) return;
  const log = Array.isArray(row.notes_log) ? [...row.notes_log] : [];
  log.push({ ts: new Date().toISOString(), text });

  try{
    const res = await fetch(`${SUPABASE_URL}/rest/v1/${TABLE_NAME}?position_id=eq.${encodeURIComponent(editingTradeNotePositionId)}`, {
      method: 'PATCH',
      headers: {
        "apikey": SUPABASE_KEY,
        "Authorization": `Bearer ${USER_ACCESS_TOKEN}`,
        "Content-Type": "application/json",
        "Prefer": "return=minimal"
      },
      body: JSON.stringify({ notes_log: log })
    });
    if(!res.ok) throw new Error(await res.text());
    row.notes_log = log;
    const normIdx = ALL_TRADES.findIndex(t => t.position_id === editingTradeNotePositionId);
    if(normIdx > -1) ALL_TRADES[normIdx].notes_log = log;
    document.getElementById('tradeNoteNewEntry').value = '';
    renderTradeNoteLog(log);
    // The Trade View modal (if that's where "Add Note" was opened from)
    // sits open in the background — refresh its Notes section immediately
    // instead of making the user close and reopen it to see the new entry.
    if(document.getElementById('tradeViewModal').classList.contains('open')) renderTradeViewModal();
  }catch(e){
    console.error("Couldn't save trade note:", e);
    errEl.textContent = "Couldn't save — make sure you've run supabase_trading_journal_add_notes_log.sql in Supabase.";
  }
}

// Carries a saved setup's Account/Position Size/Symbol/notes log into the
// same create-drawer Easy Add prefills — the timestamped log gets flattened
// into Timestamp/Comment blocks since the Trade Journal's Notes field is
// plain text.
function journalFromSetup(id){
  const s = SAVED_SETUPS.find(x => x.id === id);
  if(!s) return;
  const log = Array.isArray(s.notes_log) ? s.notes_log : [];
  const notesText = log.map(entry =>
    `${new Date(entry.ts).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'})}\n${entry.text}`
  ).join('\n\n');

  const slPct = s.stop_loss_pct != null ? Number(s.stop_loss_pct) : null;
  const tpPct = s.take_profit_pct != null ? Number(s.take_profit_pct) : null;
  const rr = (slPct && tpPct != null) ? +(tpPct / slPct).toFixed(2) : undefined;

  pendingJournalPrefill = {
    account: s.account_name || undefined,
    // The journal's position_size is a UNIT quantity (what the Upscale card's
    // bare decimal is), while the setup's position_size is dollar notional —
    // so carry the setup's quantity here, not its position_size.
    position_size: s.quantity != null ? Number(s.quantity) : undefined,
    symbol: s.symbol || undefined,
    notes: notesText || undefined,
    // Deliberately NOT risk_amount. That column exists on position_setups but
    // not on the journal: there it is derived from entry, SL and quantity and
    // rendered read-only. Putting it in the prefill is harmless for a single
    // trade — _collectDrawerPatch only reads inputs, and this one isn't — but
    // a bulk save merges the prefill straight into the insert, and Postgres
    // rejects the whole batch over a column that doesn't exist.
    rr: rr,
    trade_type: s.trade_type || undefined,
    pattern_type: s.pattern_type || undefined,
    // The PLANNED levels from the calculator — entry_price is left to the
    // pasted card (the real fill can differ from the planned entry), but
    // TP/SL are the plan by definition and have no "actual" counterpart
    // beyond close_price.
    tp_price: s.tp_price != null ? Number(s.tp_price) : undefined,
    sl_price: s.sl_price != null ? Number(s.sl_price) : undefined
  };
  pendingJournalSetupId = id;
  openEasyAddModal();
}

// Flips a saved setup's Status to "Journaled" once its trade actually gets
// saved to the Trade Journal (not just prefilled/parsed) — updates local
// state directly and only re-renders the Saved Setups table if it's the
// active view, matching the pattern used by saveSetupNotes().
async function setSetupStatus(id, status){
  try{
    const res = await fetch(`${SUPABASE_URL}/rest/v1/position_setups?id=eq.${id}`, {
      method: 'PATCH',
      headers: {
        "apikey": SUPABASE_KEY,
        "Authorization": `Bearer ${USER_ACCESS_TOKEN}`,
        "Content-Type": "application/json",
        "Prefer": "return=representation"
      },
      body: JSON.stringify({ status })
    });
    if(!res.ok) throw new Error(await res.text());
    const rows = await res.json();
    if(!rows.length) return;
    const s = SAVED_SETUPS.find(x => x.id === id);
    if(s) s.status = status;
    if(currentView === 'calculator') renderSavedSetups();
  }catch(e){
    console.error(`Couldn't set setup status to ${status}:`, e);
  }
}

async function deleteSavedSetup(id){
  if(!(await customConfirm('Delete this saved setup?'))) return;
  try{
    const res = await fetch(`${SUPABASE_URL}/rest/v1/position_setups?id=eq.${id}`, {
      method: 'DELETE',
      headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${USER_ACCESS_TOKEN}` }
    });
    if(!res.ok) throw new Error(await res.text());
    SAVED_SETUPS = SAVED_SETUPS.filter(s => s.id !== id);
    renderSavedSetups();
  }catch(e){
    console.error("Couldn't delete setup:", e);
    await customAlert("Couldn't delete this setup — please try again.");
  }
}

