function openAccountModal(id){
  editingAccountId = id || null;
  accPresetManualOverride = false;
  const a = id ? TRADING_ACCOUNTS.find(x => x.id === id) : null;

  document.getElementById('accountModalTitle').textContent = a ? 'Edit Account' : '+ Add Account';
  document.getElementById('accType').value = a ? (a.account_type || 'Prop Firm') : 'Prop Firm';
  document.getElementById('accName').value = a ? a.account_name : '';

  const knownFirm = a && PROP_FIRM_PRESETS[a.prop_firm];
  document.getElementById('accPropFirm').innerHTML =
    Object.keys(PROP_FIRM_PRESETS).map(f => `<option value="${f}">${f}</option>`).join('') + '<option value="Other">Other</option>';
  document.getElementById('accPropFirm').value = a ? (knownFirm ? a.prop_firm : 'Other') : Object.keys(PROP_FIRM_PRESETS)[0];
  document.getElementById('accPropFirmOther').value = (a && !knownFirm) ? (a.prop_firm || '') : '';

  document.getElementById('accExchangeName').value = a ? (a.exchange_name || 'Binance') : 'Binance';
  document.getElementById('accSize').value = a && a.account_size != null ? a.account_size : '';
  document.getElementById('accBalance').value = a && a.current_balance != null ? a.current_balance : '';
  document.getElementById('accRiskPerTrade').value = a && a.risk_per_trade_pct != null ? a.risk_per_trade_pct : '';
  // Hidden — not user-editable, just tells the rule summary below which
  // phase's target % to show. Phase itself only ever changes via auto-advance.
  document.getElementById('accPhase').value = a ? (a.phase || 'Evaluation Phase 1') : 'Evaluation Phase 1';
  document.getElementById('accStatus').value = a ? (a.status || 'Ongoing') : 'Ongoing';
  // A brand new account is always "Ongoing" by definition — nobody adds an
  // account that's already Passed/Failed on day one — so this only needs
  // to be seen (and correctable) once you're editing a real one later.
  document.getElementById('accStatusRow').style.display = a ? '' : 'none';
  document.getElementById('accStatusReadoutRow').style.display = a ? '' : 'none';
  if(a){
    const statusVal = a.status || 'Ongoing';
    const statusColor = statusVal === 'Passed' ? 'var(--win)' : (statusVal === 'Failed' ? 'var(--loss)' : 'var(--accent)');
    const readoutEl = document.getElementById('accStatusReadout');
    readoutEl.textContent = statusVal;
    readoutEl.style.color = statusColor;
  }
  document.getElementById('accStartDate').value = a && a.start_date ? a.start_date : (a ? '' : new Date().toISOString().slice(0,10));
  document.getElementById('accMaxDailyLoss').value = a && a.max_daily_loss_pct != null ? a.max_daily_loss_pct : '';
  document.getElementById('accMaxDrawdown').value = a && a.max_total_drawdown_pct != null ? a.max_total_drawdown_pct : '';
  document.getElementById('accProfitTarget').value = a && a.profit_target_pct != null ? a.profit_target_pct : '';
  document.getElementById('accMinDays').value = a && a.min_trading_days != null ? a.min_trading_days : '';
  document.getElementById('accMinDailyProfit').value = a && a.min_daily_profit_pct != null ? a.min_daily_profit_pct : '';
  document.getElementById('accConsistency').value = a && a.consistency_rule_pct != null ? a.consistency_rule_pct : '';
  document.getElementById('accMaxLeverage').value = a && a.max_leverage != null ? a.max_leverage : '';
  document.getElementById('accountError').textContent = '';
  document.getElementById('accountSaveBtn').textContent = a ? 'Save changes' : 'Save Account';
  document.getElementById('accountDeleteBtn').style.display = a ? 'inline-block' : 'none';

  onAccPropFirmChange(a ? a.challenge_type : null);
  toggleAccountTypeFields();

  // New account: the Prop Firm/Challenge Type/Size picker IS the task, so
  // show it expanded with no toggle. Editing an existing account: everything
  // but Balance/Status/Risk Per Trade is a rare correction, so start
  // collapsed behind a toggle instead of showing 10+ fields by default.
  document.getElementById('accFullDetailsToggle').style.display = a ? '' : 'none';
  toggleAccFullDetails(!a);

  document.getElementById('accountModal').classList.add('open');
}
function closeAccountModal(){
  document.getElementById('accountModal').classList.remove('open');
}

function toggleAccFullDetails(forceOpen){
  const wrap = document.getElementById('accFullDetailsFields');
  const isOpen = forceOpen != null ? forceOpen : (wrap.style.display === 'none');
  wrap.style.display = isOpen ? '' : 'none';
  document.getElementById('accFullDetailsToggle').textContent = isOpen ? 'Hide full account details' : 'Edit full account details';
}

function toggleAccountTypeFields(){
  const isExchange = document.getElementById('accType').value === 'Exchange';
  document.getElementById('accPropFirmFields').style.display = isExchange ? 'none' : 'block';
  document.getElementById('accPropFirmFields2').style.display = isExchange ? 'none' : 'block';
  document.getElementById('accExchangeFields').style.display = isExchange ? 'block' : 'none';

  // Name/Start Date auto-fill from the challenge preset for a new Prop Firm
  // account (nothing to derive them from otherwise) — but a new Exchange
  // account has no preset at all, so those still need to be shown.
  const hideForNewPropFirm = !editingAccountId && !isExchange;
  document.getElementById('accNameRow').style.display = hideForNewPropFirm ? 'none' : '';
  document.getElementById('accStartDateRow').style.display = hideForNewPropFirm ? 'none' : '';
}

// Re-filters Challenge Type to whichever preset firm is picked, and shows
// the free-text name field only for "Other" (a firm we don't have rules
// for). Pass the account's already-saved challenge_type (edit mode) so it
// stays selected instead of resetting to the first option.
function onAccPropFirmChange(preselectChallenge){
  const firm = document.getElementById('accPropFirm').value;
  const isOther = firm === 'Other';
  document.getElementById('accPropFirmOtherRow').style.display = isOther ? '' : 'none';

  const challengeRow = document.getElementById('accChallengeTypeRow');
  const hintEl = document.getElementById('accPresetHint');
  const preset = PROP_FIRM_PRESETS[firm];
  if(preset){
    challengeRow.style.display = '';
    hintEl.style.display = '';
    const types = Object.keys(preset);
    // New account, nothing to preselect from saved data — default straight
    // to the first challenge type instead of "— choose —", so the rule
    // summary collapses immediately on open instead of waiting for a click.
    const selected = preselectChallenge || (!editingAccountId ? types[0] : '');
    document.getElementById('accChallengeType').innerHTML =
      '<option value="">— choose —</option>' + types.map(t => `<option value="${t}" ${selected===t?'selected':''}>${t}</option>`).join('');
  }else{
    challengeRow.style.display = 'none';
    hintEl.style.display = 'none';
    document.getElementById('accChallengeType').innerHTML = '';
  }
  applyAccountPreset();
}

// Set once the user explicitly asks to override a matched preset's rules
// by hand instead of accepting them — cleared every time the modal reopens.
let accPresetManualOverride = false;

function accEditRulesManually(){
  accPresetManualOverride = true;
  applyAccountPreset();
}

// Fills Max Daily Loss/Max Drawdown/Min Trading Days/Min Daily Profit/Max
// Leverage from the matched preset, and Profit Target from whichever phase
// is currently selected (Basic: 5% at Phase 1, 8% at Phase 2). The values
// still land in the same hidden inputs saveAccount() already reads — a
// matched preset just replaces the individual number fields with a
// read-only summary instead of asking to retype 7 numbers Upscale already
// fixes for every account of that challenge.
// Selecting a preset replaces the free-typed Account Size with a dropdown
// of that challenge's real size tiers — picking one just writes straight
// into the hidden accSize input saveAccount() already reads.
function onAccSizePresetChange(){
  document.getElementById('accSize').value = document.getElementById('accSizePreset').value;
  _applyAccountNameBalanceDefaults();
}

// Account Name and Current Balance are real per-instance facts (a label
// you choose, your actual live balance) — can't be derived from the
// challenge rules the way the percentages can. What CAN be automated: a
// sensible starting guess for a brand new account, still yours to retype —
// a fresh challenge's balance IS its size on day one, and a readable name
// beats an empty field. Only fires while each is still blank, so it never
// overwrites something you already typed or an account being edited.
function _applyAccountNameBalanceDefaults(){
  if(editingAccountId) return;
  const firm = document.getElementById('accPropFirm').value;
  const challenge = document.getElementById('accChallengeType').value;
  const size = document.getElementById('accSize').value;
  if(!size) return;

  const nameEl = document.getElementById('accName');
  if(!nameEl.value.trim()){
    const sizeLabel = Number(size) >= 1000 ? `${Number(size)/1000}K` : size;
    nameEl.value = challenge ? `${firm} ${challenge} ${sizeLabel}` : `${firm} ${sizeLabel}`;
  }

  const balEl = document.getElementById('accBalance');
  if(!balEl.value.trim()) balEl.value = size;
}

function applyAccountPreset(){
  const firm = document.getElementById('accPropFirm').value;
  const challenge = document.getElementById('accChallengeType').value;
  const preset = PROP_FIRM_PRESETS[firm]?.[challenge];
  const manualEl = document.getElementById('accManualRuleFields');
  const summaryEl = document.getElementById('accPresetSummary');
  const sizePresetRow = document.getElementById('accSizePresetRow');
  const sizeManualRow = document.getElementById('accSizeManualRow');

  if(preset?.sizes){
    const currentSize = document.getElementById('accSize').value;
    document.getElementById('accSizePreset').innerHTML = preset.sizes
      .map(sz => `<option value="${sz}" ${String(sz)===currentSize?'selected':''}>$${sz.toLocaleString()}</option>`).join('');
    if(!preset.sizes.some(sz => String(sz) === currentSize)){
      document.getElementById('accSize').value = preset.sizes[0];
      document.getElementById('accSizePreset').value = preset.sizes[0];
    }
    sizePresetRow.style.display = '';
    sizeManualRow.style.display = 'none';
  }else{
    sizePresetRow.style.display = 'none';
    sizeManualRow.style.display = '';
  }
  _applyAccountNameBalanceDefaults();

  if(!preset){
    manualEl.style.display = '';
    summaryEl.style.display = 'none';
    return;
  }

  const setIf = (id, val) => { document.getElementById(id).value = (val != null) ? val : ''; };
  setIf('accMaxDailyLoss', preset.maxDailyLossPct);
  setIf('accMaxDrawdown', preset.maxTotalDrawdownPct);
  setIf('accMinDays', preset.minTradingDays);
  setIf('accMinDailyProfit', preset.minDailyProfitPct);
  setIf('accMaxLeverage', preset.maxLeverage);

  const phase = document.getElementById('accPhase').value;
  const targetPct = phase === 'Evaluation Phase 2' ? preset.phase2TargetPct : preset.phase1TargetPct;
  document.getElementById('accProfitTarget').value = targetPct != null ? targetPct : '';

  if(accPresetManualOverride){
    manualEl.style.display = '';
    summaryEl.style.display = 'none';
    return;
  }

  manualEl.style.display = 'none';
  summaryEl.style.display = '';
  const rows = [
    preset.maxDailyLossPct != null ? `Daily Loss <strong>${preset.maxDailyLossPct}%</strong>` : null,
    preset.maxTotalDrawdownPct != null ? `Max Drawdown <strong>${preset.maxTotalDrawdownPct}%</strong>` : null,
    targetPct != null ? `Profit Target <strong>${targetPct}%</strong> (${phase})` : null,
    preset.minTradingDays != null ? `Min Trading Days <strong>${preset.minTradingDays}</strong>` : null,
    preset.minDailyProfitPct != null ? `Min Daily Profit <strong>${preset.minDailyProfitPct}%</strong>` : null,
    preset.maxLeverage != null ? `Max Leverage <strong>x${preset.maxLeverage}</strong>` : null,
  ].filter(Boolean).map(r => `<div>${r}</div>`).join('');
  summaryEl.innerHTML = rows + `<div style="margin-top:6px;"><a href="#" onclick="event.preventDefault(); accEditRulesManually();" style="color:var(--accent);">Edit these manually instead</a></div>`;
}

function _numOrNull(id){
  const v = document.getElementById(id).value;
  return v === '' ? null : parseFloat(v);
}

async function saveAccount(){
  const errEl = document.getElementById('accountError');
  const btn = document.getElementById('accountSaveBtn');
  errEl.textContent = '';

  const accountName = document.getElementById('accName').value.trim();
  if(!accountName){ errEl.textContent = 'Account name is required.'; return; }

  btn.disabled = true;
  btn.textContent = 'Saving…';

  const accountType = document.getElementById('accType').value;
  const isExchange = accountType === 'Exchange';
  const propFirmSel = document.getElementById('accPropFirm').value;
  const propFirmName = propFirmSel === 'Other' ? document.getElementById('accPropFirmOther').value.trim() : propFirmSel;
  const challengeType = (!isExchange && PROP_FIRM_PRESETS[propFirmSel]) ? (document.getElementById('accChallengeType').value || null) : null;

  const payload = {
    account_type: accountType,
    account_name: accountName,
    account_size: isExchange ? null : _numOrNull('accSize'),
    current_balance: _numOrNull('accBalance'),
    start_date: document.getElementById('accStartDate').value || null,
    risk_per_trade_pct: isExchange ? null : _numOrNull('accRiskPerTrade'),
    prop_firm: isExchange ? null : (propFirmName || null),
    challenge_type: isExchange ? null : challengeType,
    max_leverage: isExchange ? null : _numOrNull('accMaxLeverage'),
    status: isExchange ? 'Ongoing' : document.getElementById('accStatus').value,
    max_daily_loss_pct: isExchange ? null : _numOrNull('accMaxDailyLoss'),
    max_total_drawdown_pct: isExchange ? null : _numOrNull('accMaxDrawdown'),
    profit_target_pct: isExchange ? null : _numOrNull('accProfitTarget'),
    min_trading_days: isExchange ? null : (document.getElementById('accMinDays').value === '' ? null : parseInt(document.getElementById('accMinDays').value, 10)),
    min_daily_profit_pct: isExchange ? null : _numOrNull('accMinDailyProfit'),
    consistency_rule_pct: isExchange ? null : _numOrNull('accConsistency'),
    exchange_name: isExchange ? document.getElementById('accExchangeName').value : null
  };

  // Phase / Phase Start Date / Phase Start Balance have no visible control
  // anymore — set once, on creation, then left alone. Editing an existing
  // account never touches them here; only _autoAdvanceAccountPhases() does.
  if(!isExchange && !editingAccountId){
    payload.phase = 'Evaluation Phase 1';
    payload.phase_start_date = payload.start_date;
    payload.phase_start_balance = payload.current_balance;
  }

  try{
    const res = editingAccountId
      ? await fetch(`${SUPABASE_URL}/rest/v1/trading_accounts?id=eq.${editingAccountId}`, {
          method: 'PATCH',
          headers: {
            "apikey": SUPABASE_KEY,
            "Authorization": `Bearer ${USER_ACCESS_TOKEN}`,
            "Content-Type": "application/json",
            "Prefer": "return=minimal"
          },
          body: JSON.stringify(payload)
        })
      : await fetch(`${SUPABASE_URL}/rest/v1/trading_accounts`, {
          method: 'POST',
          headers: {
            "apikey": SUPABASE_KEY,
            "Authorization": `Bearer ${USER_ACCESS_TOKEN}`,
            "Content-Type": "application/json",
            "Prefer": "return=minimal"
          },
          body: JSON.stringify([payload])
        });
    if(!res.ok) throw new Error(await res.text());

    closeAccountModal();
    await loadAccounts();
    showToast(editingAccountId ? 'Account updated' : 'Account added');
  }catch(e){
    console.error("Couldn't save account:", e);
    let hint = '';
    try{
      const parsed = JSON.parse(e.message);
      if(parsed.message) hint = parsed.message;
    }catch(_){ hint = e.message || ''; }
    errEl.textContent = hint ? `Couldn't save — ${hint}` : "Couldn't save — please try again.";
  }finally{
    btn.disabled = false;
    btn.textContent = editingAccountId ? 'Save changes' : 'Save Account';
  }
}

async function deleteAccount(){
  if(!editingAccountId) return;
  if(!(await customConfirm('Delete this account? This cannot be undone.'))) return;
  try{
    const res = await fetch(`${SUPABASE_URL}/rest/v1/trading_accounts?id=eq.${editingAccountId}`, {
      method: 'DELETE',
      headers: {
        "apikey": SUPABASE_KEY,
        "Authorization": `Bearer ${USER_ACCESS_TOKEN}`,
        "Prefer": "return=minimal"
      }
    });
    if(!res.ok) throw new Error(await res.text());
    closeAccountModal();
    await loadAccounts();
    showToast('Account deleted');
  }catch(e){
    console.error("Couldn't delete account:", e);
    await customAlert("Couldn't delete — please try again.");
  }
}

/* ---------------- Notebook ---------------- */
let NOTES = [];
let editingNoteId = null;
let viewingNoteId = null;
const NOTE_TAGS = ['General','Strategy','Psychology','Market Notes','Trade Review','Accounts'];
const NOTE_TAG_PILL_CLASS = {
  Strategy: 'pill-orange',
  Psychology: 'pill-red',
  'Market Notes': 'pill-green',
  'Trade Review': 'pill-muted',
  Accounts: 'pill-blue',
  General: 'pill-muted'
};
let activeNoteTagFilter = 'All';

async function loadNotes(){
  try{
    const res = await fetch(`${SUPABASE_URL}/rest/v1/notebook_entries?select=*&order=updated_at.desc`, {
      headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${USER_ACCESS_TOKEN}` }
    });
    if(!res.ok) throw new Error(await res.text());
    NOTES = await res.json();
  }catch(e){
    console.error("Couldn't load notes:", e);
    NOTES = [];
  }
  renderNoteTagFilters();
  renderNoteList();
}

function renderNoteTagFilters(){
  const row = document.getElementById('noteTagFilterRow');
  if(!row) return;
  const tags = ['All', ...NOTE_TAGS];
  row.innerHTML = tags.map(t =>
    `<span class="tag-filter ${activeNoteTagFilter===t?'active':''}" onclick="switchNoteTagFilter('${t}')">${t}</span>`
  ).join('');
}

function switchNoteTagFilter(tag){
  activeNoteTagFilter = tag;
  renderNoteTagFilters();
  renderNoteList();
}

// Pinned above real notes, always visible regardless of search/tag filter —
// a live confluence-checklist reference, not an actual notebook_entries row
// (nothing about it is saved).
function _breadButterListItemHtml(){
  return `
    <div class="note-item ${viewingNoteId==='breadbutter'?'selected':''}" onclick="openBreadButterChecklist()">
      <div class="note-item-top">
        <span class="note-item-title">🍞 Bread &amp; Butter Setup</span>
      </div>
      <div class="note-item-snippet">Live confluence checklist reference</div>
      <span class="pill pill-muted">Checklist</span>
    </div>
  `;
}

function renderNoteList(){
  const wrap = document.getElementById('noteListItems');
  if(!wrap) return;
  const search = (document.getElementById('noteSearchInput')?.value || '').trim().toLowerCase();

  let list = NOTES;
  if(activeNoteTagFilter !== 'All') list = list.filter(n => (n.tag || 'General') === activeNoteTagFilter);
  if(search) list = list.filter(n => (n.title||'').toLowerCase().includes(search) || (n.body||'').toLowerCase().includes(search));

  if(!list.length){
    wrap.innerHTML = _breadButterListItemHtml() + `<div class="empty-state">No notes yet — click "+ New Note" to start writing.</div>`;
    return;
  }

  wrap.innerHTML = _breadButterListItemHtml() + list.map(n => {
    const dateLabel = n.updated_at ? new Date(n.updated_at).toLocaleDateString('en-US',{month:'short',day:'numeric'}) : '';
    const snippet = (n.body || '').replace(/\s+/g,' ').trim();
    const tagClass = NOTE_TAG_PILL_CLASS[n.tag] || 'pill-muted';
    return `
      <div class="note-item ${viewingNoteId===n.id?'selected':''}" onclick="selectNote(${n.id})">
        <div class="note-item-top">
          <span class="note-item-title">${escapeHtml(n.title || 'Untitled')}</span>
          <span class="note-item-date">${dateLabel}</span>
        </div>
        <div class="note-item-snippet">${escapeHtml(snippet) || '—'}</div>
        <span class="pill ${tagClass}">${escapeHtml(n.tag || 'General')}</span>
      </div>
    `;
  }).join('');
}

function openNoteModal(id){
  editingNoteId = id || null;
  const n = id ? NOTES.find(x => x.id === id) : null;
  document.getElementById('noteModalTitle').textContent = n ? 'Edit Note' : '+ New Note';
  document.getElementById('noteTitleInput').value = n ? (n.title || '') : '';
  document.getElementById('noteTagSelect').value = n ? (n.tag || 'General') : 'General';
  document.getElementById('noteBodyInput').value = n ? (n.body || '') : '';
  document.getElementById('noteModalError').textContent = '';
  document.getElementById('noteModal').classList.add('open');
}

function closeNoteModal(){
  document.getElementById('noteModal').classList.remove('open');
}

async function saveNote(){
  const errEl = document.getElementById('noteModalError');
  errEl.textContent = '';
  const title = document.getElementById('noteTitleInput').value.trim();
  if(!title){ errEl.textContent = 'Please add a title.'; return; }

  const btn = document.getElementById('noteSaveBtn');
  btn.disabled = true;
  btn.textContent = 'Saving…';

  const payload = {
    title,
    tag: document.getElementById('noteTagSelect').value,
    body: document.getElementById('noteBodyInput').value,
    updated_at: new Date().toISOString()
  };

  try{
    const res = editingNoteId
      ? await fetch(`${SUPABASE_URL}/rest/v1/notebook_entries?id=eq.${editingNoteId}`, {
          method: 'PATCH',
          headers: {
            "apikey": SUPABASE_KEY, "Authorization": `Bearer ${USER_ACCESS_TOKEN}`,
            "Content-Type": "application/json", "Prefer": "return=minimal"
          },
          body: JSON.stringify(payload)
        })
      : await fetch(`${SUPABASE_URL}/rest/v1/notebook_entries`, {
          method: 'POST',
          headers: {
            "apikey": SUPABASE_KEY, "Authorization": `Bearer ${USER_ACCESS_TOKEN}`,
            "Content-Type": "application/json", "Prefer": "return=minimal"
          },
          body: JSON.stringify([payload])
        });
    if(!res.ok) throw new Error(await res.text());
    const wasEditing = editingNoteId;
    closeNoteModal();
    await loadNotes();
    if(wasEditing) selectNote(wasEditing);
    showToast(wasEditing ? 'Note updated' : 'Note created');
  }catch(e){
    console.error("Couldn't save note:", e);
    errEl.textContent = "Couldn't save — please try again.";
  }finally{
    btn.disabled = false;
    btn.textContent = 'Save';
  }
}

function selectNote(id){
  const n = NOTES.find(x => x.id === id);
  if(!n) return;
  viewingNoteId = id;

  document.getElementById('noteDetailEmpty').style.display = 'none';
  document.getElementById('noteDetailChecklistWrap').style.display = 'none';
  document.getElementById('noteDetailWrap').style.display = 'block';
  document.getElementById('noteDetailTitle').textContent = n.title || 'Untitled';
  const tagEl = document.getElementById('noteDetailTag');
  tagEl.textContent = n.tag || 'General';
  tagEl.className = 'pill ' + (NOTE_TAG_PILL_CLASS[n.tag] || 'pill-muted');
  document.getElementById('noteDetailDate').textContent = n.updated_at
    ? `Last edited ${new Date(n.updated_at).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'})}`
    : '';
  document.getElementById('noteDetailText').textContent = n.body || '';

  renderNoteList();
}

function editSelectedNote(){
  if(viewingNoteId) openNoteModal(viewingNoteId);
}

/* ---- Notebook > "Bread & Butter Setup" — live confluence checklist
   reference, pinned above real notes. Pure scratch tool: pick Trade Type +
   Pattern Type, tick through the same checklist used on a real Setup, get
   a fast read on whether the trade you're looking at qualifies. Nothing
   here is saved anywhere — its own state, kept separate from
   confluenceTarget/confluenceAnswers (the Setup/trade-linked version). */
let bbAnswers = {};
let bbChartPattern = null;

function openBreadButterChecklist(){
  viewingNoteId = 'breadbutter';
  document.getElementById('noteDetailEmpty').style.display = 'none';
  document.getElementById('noteDetailWrap').style.display = 'none';
  document.getElementById('noteDetailChecklistWrap').style.display = 'block';

  document.getElementById('bbTradeType').innerHTML =
    '<option value="">— choose —</option>' + FIELD_OPTIONS.trade_type.map(o => `<option value="${o}">${o}</option>`).join('');
  _renderBbPatternOptions();
  bbAnswers = {};
  bbChartPattern = null;
  renderBbChecklist();
  renderNoteList();
}

function _renderBbPatternOptions(){
  const tt = document.getElementById('bbTradeType').value;
  const allowed = _patternTypesForTradeType(tt);
  const sel = document.getElementById('bbPatternType');
  const current = sel.value;
  sel.innerHTML = '<option value="">— choose —</option>' + allowed.map(o => `<option value="${o}">${o}</option>`).join('');
  if(current && allowed.includes(current)) sel.value = current;
}

function onBbTradeTypeChange(){
  _renderBbPatternOptions();
  onBbTypeChange();
}

function onBbTypeChange(){
  bbAnswers = {};
  bbChartPattern = null;
  renderBbChecklist();
}

function setBbAnswer(i, val){
  bbAnswers[i] = (bbAnswers[i] === val) ? undefined : val;
  if(bbAnswers[i] === undefined) delete bbAnswers[i];
  const tt = document.getElementById('bbTradeType')?.value;
  const pt = document.getElementById('bbPatternType')?.value;
  const cfg = CONFLUENCE_SETUPS[`${tt}|${pt}`];
  if(cfg) _applyConfluenceImplications(cfg.items, bbAnswers, i);
  renderBbChecklist();
}

function selectBbChartPattern(p){
  bbChartPattern = (p === 'None') ? null : p;
  renderBbChecklist();
}

// Shared by both Bread & Butter checklists — the Notebook's scratch copy and
// the Calculator's saved one. Identical markup and behaviour; only the element
// ids, the state they read, and the handler names they call differ.
function _bbRenderChecklist({ ttId, ptId, bodyId, answers, chartPattern, setAnswerFn, setPatternFn }){
  const body = document.getElementById(bodyId);
  if(!body) return;
  const tt = document.getElementById(ttId).value;
  const pt = document.getElementById(ptId).value;
  const key = (tt && pt) ? `${tt}|${pt}` : null;
  if(!key){
    body.innerHTML = '<div class="empty-state">Pick a Trade Type and Pattern Type first.</div>';
    return;
  }
  const cfg = CONFLUENCE_SETUPS[key];
  if(!cfg){
    body.innerHTML = '<div class="empty-state">No confluence checklist configured for this combination yet.</div>';
    return;
  }

  const { total, done, unanswered } = _confluenceProgress(cfg.items, answers, !!chartPattern);

  const itemsHtml = cfg.items.map((it, i) =>
    _renderConfluenceItemRow(it, i, answers[i], setAnswerFn)
  ).join('');

  const chipsHtml = ['None', ..._confluencePatternChoices(cfg, chartPattern)].map(p => {
    const isActive = (p === 'None' && !chartPattern) || p === chartPattern;
    return `<span class="cfl-pattern-chip ${p==='None'?'cfl-none':''} ${isActive?'active':''}" onclick="${setPatternFn}('${p.replace(/'/g,"\\'")}')">${p}</span>`;
  }).join('');

  body.innerHTML = `
    <div class="cfl-checklist-head">
      <div class="cfl-checklist-title">Confluence Checklist</div>
      <div class="cfl-progress-chip">
        <span class="cfl-progress-track"><span class="cfl-progress-fill" style="width:${total?(done/total*100):0}%;"></span></span>
        <span class="num">${Number(done.toFixed(1))}/${total}</span>
      </div>
    </div>
    ${unanswered > 0 ? `<div class="cfl-unanswered-note">${unanswered} question${unanswered===1?'':'s'} not yet answered</div>` : ''}
    <div class="cfl-checklist-card">${itemsHtml}</div>
    <div class="cfl-pattern-picker">
      <div class="cfl-pattern-picker-head">
        <span class="cfl-pattern-picker-title">Chart Pattern</span>
      </div>
      <div class="cfl-pattern-chips">${chipsHtml}</div>
    </div>
    ${_bbWarningSignsHtml(key, cfg, done, total, answers)}
  `;
}

function renderBbChecklist(){
  _bbRenderChecklist({
    ttId: 'bbTradeType', ptId: 'bbPatternType', bodyId: 'bbChecklistBody',
    answers: bbAnswers, chartPattern: bbChartPattern,
    setAnswerFn: 'setBbAnswer', setPatternFn: 'selectBbChartPattern'
  });
}

// Reads your own journal back to you while the setup is still live: how this
// exact setup has performed, how trades at this confluence level went, and
// which of the answers you've just given have preceded losses before.
// Every claim carries its sample size — with a handful of trades these are
// observations, not predictions, and the copy says so rather than pretending
// otherwise.
// Two floors, because the levels differ in how much data reaches them. A
// whole setup accumulates trades quickly, so 3 is enough to say anything at
// all. A single answer on a single question inside that setup does not — at
// 3 trades a 33% vs 67% split is chance, so those flags wait for 5.
const BB_MIN_SAMPLE = 3;
const BB_MIN_ANSWER_SAMPLE = 5;

function _bbStats(trades){
  const wins = trades.filter(t => (t.win_loss||'').toLowerCase() === 'win').length;
  const losses = trades.filter(t => ['loss','liquidated'].includes((t.win_loss||'').toLowerCase())).length;
  const decided = wins + losses;
  const net = trades.reduce((s,t) => s + netPnl(t), 0);
  return {
    n: trades.length,
    winRate: decided ? wins / decided * 100 : null,
    net,
    avg: trades.length ? net / trades.length : 0
  };
}

// `answers` is passed in rather than read off a module global, because this
// panel now renders for two independent checklists (Notebook + Calculator).
function _bbWarningSignsHtml(key, cfg, done, total, answers){
  const sameSetup = ALL_TRADES.filter(t =>
    t.close_date && `${t.trade_type}|${t.pattern_type}` === key
  );

  if(sameSetup.length < BB_MIN_SAMPLE){
    return `<div class="bb-warn bb-warn-neutral">
      <div class="bb-warn-top">
        <span class="bb-verdict">NO DATA</span>
        <span class="bb-warn-head">Not enough history yet</span>
      </div>
      <div class="bb-warn-body" style="margin-top:8px;">You've journaled ${sameSetup.length} trade${sameSetup.length===1?'':'s'} on this setup. Once there are a few more, this panel will tell you how it has actually performed for you.</div>
    </div>`;
  }

  const all = _bbStats(sameSetup);
  const flags = [];

  // 1. How trades at this confluence level have gone. Compared as a FRACTION,
  //    since different setups have different question counts.
  const nowFrac = total ? done / total : 0;
  const scored = sameSetup
    .map(t => ({ t, f: _confluenceScoreFor(t) }))
    .filter(x => x.f !== null);
  const withConfluence = scored.length;
  const band = scored.filter(x => Math.abs(x.f - nowFrac) <= 0.15).map(x => x.t);
  // The band is the primary evidence, and it is judged on what ACTUALLY
  // happened — never on the assumption that a low score is bad. If your 4/9
  // trades have historically won, this says so and the verdict follows it.
  let bandStats = null;
  if(band.length >= BB_MIN_SAMPLE){
    bandStats = _bbStats(band);
    const s = bandStats;
    if(s.winRate !== null && s.avg < 0){
      flags.push({ level:'bad', text:`At around this confluence level (${fmtNum(nowFrac*100,0)}%), your ${s.n} trades won ${fmtNum(s.winRate,0)}% of the time and averaged ${fmtMoney(s.avg)} — a loss on average.` });
    }else if(s.winRate !== null && s.avg > 0){
      flags.push({ level:'good', text:`At around this confluence level (${fmtNum(nowFrac*100,0)}%), your ${s.n} trades won ${fmtNum(s.winRate,0)}% of the time and averaged ${fmtMoney(s.avg)} — profitable on average${nowFrac < 0.6 ? ', even at this score' : ''}.` });
    }
  }

  // 2. Individual answers you've picked that carry a losing record. Compared
  //    against your record on this setup overall, so it flags what's actually
  //    worse for you rather than anything that merely sits below 50%.
  const answerLabel = { yes:'Yes', no:'No', retest:'Retest', almost:'Almost' };
  cfg.items.forEach((it, i) => {
    const ans = answers[i];
    if(ans === undefined || all.winRate === null) return;
    const matching = sameSetup.filter(t => t.confluence_answers && t.confluence_answers[i] === ans);
    if(matching.length < BB_MIN_ANSWER_SAMPLE) return;
    const s = _bbStats(matching);
    if(s.winRate === null) return;

    const label = it.select ? `${it.tag} “${ans}”` : `“${answerLabel[ans] || ans}” on ${it.tag}`;
    if(s.winRate <= all.winRate - 15){
      flags.push({ level:'bad', text:`${label} — ${fmtNum(s.winRate,0)}% win rate over ${s.n} trades, against ${fmtNum(all.winRate,0)}% on this setup overall.` });
    }else if(s.winRate >= all.winRate + 15){
      flags.push({ level:'good', text:`${label} — ${fmtNum(s.winRate,0)}% win rate over ${s.n} trades, better than your ${fmtNum(all.winRate,0)}% overall.` });
    }
  });

  const bad = flags.filter(f => f.level === 'bad').length;
  const good = flags.filter(f => f.level === 'good').length;
  const overall = all.winRate === null ? 'no decided results yet' : `${fmtNum(all.winRate,0)}% win rate`;

  // Gated on how many questions are ANSWERED, not on the score. Those are
  // different things: a fully answered checklist that lands on 3/9 is a
  // complete, low-confluence read — not an unfinished one — and treating it
  // as unfinished was hiding exactly the case where history disagrees with
  // the score.
  const answeredCount = cfg.items.filter((_, i) => answers[i] !== undefined).length;
  const mostlyAnswered = answeredCount >= Math.ceil(cfg.items.length * 0.6);

  let level, head, body, verdict;
  if(!mostlyAnswered){
    level = 'neutral'; verdict = 'INCOMPLETE';
    head = 'Keep filling this in';
    body = `${answeredCount} of ${cfg.items.length} questions answered — too few to compare against your history yet. Your record on this setup: ${all.n} trades, ${overall}, ${fmtMoney(all.net)} total.`;
  }else if(bandStats && bandStats.avg > 0 && bad === 0){
    // History says setups like this one make money, whatever the score is.
    level = 'good'; verdict = 'GOOD';
    head = nowFrac < 0.6 ? 'Low score, but this has worked for you' : 'This matches what works for you';
    body = `Setups at this confluence level have averaged ${fmtMoney(bandStats.avg)} across ${bandStats.n} of your trades${bandStats.winRate !== null ? ` at a ${fmtNum(bandStats.winRate,0)}% win rate` : ''}. The score alone isn't the reason to skip it.`;
  }else if(bandStats && bandStats.avg < 0 && good === 0){
    level = 'bad'; verdict = 'RISKY';
    head = 'This one looks risky';
    body = `Setups at this confluence level have averaged ${fmtMoney(bandStats.avg)} across ${bandStats.n} of your trades${bandStats.winRate !== null ? ` at a ${fmtNum(bandStats.winRate,0)}% win rate` : ''}. Your overall record on this setup is ${overall}.`;
  }else if(bad > good){
    level = 'bad'; verdict = 'RISKY';
    head = 'This one looks risky';
    body = `${bad} thing${bad===1?' here has':'s here have'} gone badly for you before. Your overall record on this setup is ${overall} over ${all.n} trades — this particular combination has done worse.`;
  }else if(good > 0 && bad === 0){
    level = 'good'; verdict = 'GOOD';
    head = 'This matches what works for you';
    body = `Nothing here carries a losing record, and ${good} thing${good===1?' has':'s have'} done better than your ${overall} on this setup (${all.n} trades).`;
  }else{
    level = 'neutral'; verdict = 'MIXED';
    head = 'Mixed signals';
    body = `No strong signal either way from your ${all.n} trades on this setup (${overall}, ${fmtMoney(all.net)} total).`;
  }

  // The glance layer: a verdict word and four numbers, sized to be read
  // without reading. Everything else is one click away, because the moment
  // this panel matters most is the moment there's least patience for prose.
  // Stats describe the closest comparison available — trades at this
  // confluence level if there are enough of them, otherwise the setup overall.
  const src = bandStats || all;
  const srcLabel = bandStats ? 'at this level' : 'on this setup';
  const stats = [
    { v: `${fmtNum(nowFrac*100,0)}%`, l: 'score' },
    { v: src.n, l: srcLabel },
    { v: src.winRate === null ? '—' : `${fmtNum(src.winRate,0)}%`, l: 'win rate' },
    { v: fmtMoney(src.avg), l: 'avg', tone: src.avg > 0 ? 'good' : (src.avg < 0 ? 'bad' : '') }
  ];

  const detailCount = flags.length;
  return `<div class="bb-warn bb-warn-${level}">
    <div class="bb-warn-top">
      <span class="bb-verdict">${verdict}</span>
      <span class="bb-warn-head">${head}</span>
    </div>
    <div class="bb-warn-stats">${stats.map(s =>
      `<span class="bb-stat${s.tone ? ' bb-stat-' + s.tone : ''}"><b>${s.v}</b><i>${s.l}</i></span>`
    ).join('')}</div>
    <details class="bb-warn-more">
      <summary>${detailCount ? `Why — ${detailCount} signal${detailCount===1?'':'s'}` : 'Details'}</summary>
      <div class="bb-warn-body">${body}</div>
      ${flags.length ? `<div class="bb-warn-list">${flags.map(f =>
        `<div class="bb-warn-item bb-warn-item-${f.level}">${f.text}</div>`
      ).join('')}</div>` : ''}
      <div class="bb-warn-foot">From your own journal: <strong>${all.n}</strong> trades on this setup, <strong>${withConfluence}</strong> with a filled-in checklist${band.length ? `, <strong>${band.length}</strong> at a similar confluence level` : ''}. ${all.n < 10 ? 'Still a small sample — read these as observations, not predictions.' : 'Per-answer flags only appear once an answer has ' + BB_MIN_ANSWER_SAMPLE + '+ trades behind it.'}</div>
    </details>
  </div>`;
}

async function deleteSelectedNote(){
  if(!viewingNoteId) return;
  if(!(await customConfirm('Delete this note permanently? This cannot be undone.'))) return;
  try{
    const res = await fetch(`${SUPABASE_URL}/rest/v1/notebook_entries?id=eq.${viewingNoteId}`, {
      method: 'DELETE',
      headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${USER_ACCESS_TOKEN}`, "Prefer": "return=minimal" }
    });
    if(!res.ok) throw new Error(await res.text());
    viewingNoteId = null;
    document.getElementById('noteDetailWrap').style.display = 'none';
    document.getElementById('noteDetailEmpty').style.display = 'block';
    await loadNotes();
    showToast('Note deleted');
  }catch(e){
    console.error("Couldn't delete note:", e);
    await customAlert("Couldn't delete — please try again.");
  }
}

/* ---------- Diary (mood check-in) ---------- */
// sentiment drives the color coding in both the picker (selection ring) and
// the view-mode badge — positive/neutral/negative, not a color per mood.
const MOOD_OPTIONS = [
  { key: 'great', emoji: '😄', label: 'Great', sentiment: 'positive' },
  { key: 'good', emoji: '🙂', label: 'Good', sentiment: 'positive' },
  { key: 'okay', emoji: '😐', label: 'Okay', sentiment: 'neutral' },
  { key: 'down', emoji: '😔', label: 'Down', sentiment: 'negative' },
  { key: 'anxious', emoji: '😰', label: 'Anxious', sentiment: 'negative' },
  { key: 'angry', emoji: '😡', label: 'Angry', sentiment: 'negative' },
  { key: 'sick', emoji: '🤒', label: 'Sick', sentiment: 'negative' }
];

let MOOD_ENTRIES = [];
let moodCalMonth = new Date();
let editingMoodDate = null;
let selectedMoodKey = null;

function _moodTodayISO(){
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}

async function loadMoodEntries(){
  try{
    const res = await fetch(`${SUPABASE_URL}/rest/v1/mood_entries?select=*`, {
      headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${USER_ACCESS_TOKEN}` }
    });
    if(!res.ok) throw new Error(await res.text());
    MOOD_ENTRIES = await res.json();
  }catch(e){
    console.error("Couldn't load mood entries:", e);
    MOOD_ENTRIES = [];
  }
  renderMoodCalendar();
}

function shiftMoodMonth(dir){
  moodCalMonth.setMonth(moodCalMonth.getMonth() + dir);
  renderMoodCalendar();
}

function renderMoodCalendar(){
  const grid = document.getElementById('moodCalGrid');
  if(!grid) return;
  const y = moodCalMonth.getFullYear(), m = moodCalMonth.getMonth();
  document.getElementById('moodCalLabel').textContent = moodCalMonth.toLocaleDateString('en-US',{month:'long', year:'numeric'});

  const byDate = {};
  MOOD_ENTRIES.forEach(e => { byDate[e.entry_date] = e; });

  const firstDow = new Date(y, m, 1).getDay();
  const daysInMonth = new Date(y, m+1, 0).getDate();
  const dows = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  let html = dows.map(d => `<div class="cal-dow">${d}</div>`).join('');

  for(let i=0;i<firstDow;i++) html += `<div class="cal-cell empty"></div>`;

  const todayISO = _moodTodayISO();
  for(let d=1; d<=daysInMonth; d++){
    const iso = `${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
    const entry = byDate[iso];
    const mood = entry ? MOOD_OPTIONS.find(o => o.key === entry.mood) : null;
    html += `<div class="cal-cell${iso === todayISO ? ' today' : ''}" onclick="openMoodModal('${iso}')">
      <div class="d">${d}</div>
      ${mood ? `<div class="mood-emoji" title="${escapeHtml(mood.label)}">${mood.emoji}</div><div class="mood-cell-label">${escapeHtml(mood.label)}</div>` : ''}
    </div>`;
  }

  const totalCells = firstDow + daysInMonth;
  const remainder = totalCells % 7;
  if(remainder !== 0) for(let i=0; i<7-remainder; i++) html += `<div class="cal-cell empty"></div>`;

  grid.innerHTML = html;
  // Called from here rather than from each of the five places that redraw the
  // calendar (load, month shift, save, delete) — cheap enough at a dozen rows,
  // and it can't be forgotten when a sixth call site appears.
  renderMoodRecent();
}

// Recent written entries, newest first. The calendar answers "how was the
// month"; this answers "what did I actually write", which needed a click per
// day to find out before. Only entries with text appear — a mood on its own
// has nothing to read.
const MOOD_RECENT_LIMIT = 12;
function renderMoodRecent(){
  const list = document.getElementById('moodRecentList');
  if(!list) return;
  const filter = document.getElementById('moodRecentFilter')?.value || 'all';

  const rows = MOOD_ENTRIES
    .filter(e => e.entry_date && (filter === 'all' ? _moodEntryHasText(e) : (e[filter] || '').trim()))
    .sort((a,b) => (a.entry_date < b.entry_date ? 1 : -1))
    .slice(0, MOOD_RECENT_LIMIT);

  if(!rows.length){
    list.innerHTML = `<div class="empty-state">${filter === 'all'
      ? 'Nothing written yet — pick a day on the calendar and jot something down.'
      : 'No entries with anything under that section yet.'}</div>`;
    return;
  }

  list.innerHTML = rows.map(e => {
    const mood = MOOD_OPTIONS.find(o => o.key === e.mood);
    const d = new Date(e.entry_date + 'T00:00:00');
    // When a section is picked, show only that section's text — otherwise the
    // preview would be dominated by whichever section happened to be longest.
    const shown = filter === 'all'
      ? MOOD_SECTIONS.filter(s => (e[s.key] || '').trim())
      : MOOD_SECTIONS.filter(s => s.key === filter);
    return `
      <div class="mood-recent" onclick="openMoodModal('${e.entry_date}')">
        <div class="mood-recent-top">
          <span class="mood-recent-date">${d.toLocaleDateString('en-US',{weekday:'short', month:'short', day:'numeric'})}</span>
          ${mood ? `<span class="mood-recent-mood mood-view-badge-${mood.sentiment}">${mood.emoji} ${escapeHtml(mood.label)}</span>` : ''}
        </div>
        ${shown.map(s => `
          <div class="mood-recent-line">
            ${s.icon ? `<span class="mood-recent-tag">${s.icon} ${s.label}</span>` : `<span class="mood-recent-tag">${s.label}</span>`}
            <span class="mood-recent-text">${escapeHtml(e[s.key].trim())}</span>
          </div>`).join('')}
      </div>`;
  }).join('');
}

// One tidy row of circular emoji dots (instead of 7 bordered boxes each
// carrying its own label, which wrapped messily) — the selected mood's
// name shows once, below the row, so the row itself stays uncluttered.
function renderMoodPicker(){
  const dotsHtml = MOOD_OPTIONS.map(o => `
    <button type="button" class="mood-dot mood-dot-${o.sentiment}${selectedMoodKey === o.key ? ' selected' : ''}" onclick="selectMood('${o.key}')" title="${escapeHtml(o.label)}">${o.emoji}</button>
  `).join('');
  const selected = MOOD_OPTIONS.find(o => o.key === selectedMoodKey);
  document.getElementById('moodPicker').innerHTML = `
    <div class="mood-dot-row">${dotsHtml}</div>
    <div class="mood-picker-label">${selected ? escapeHtml(selected.label) : 'Pick how you felt'}</div>
  `;
}

function selectMood(key){
  selectedMoodKey = key;
  renderMoodPicker();
}

// Clicking a day opens straight into a read-only VIEW layout when it
// already has an entry (mood + note, like a diary page) with a pencil
// button to switch into the edit form — days with nothing logged yet go
// straight to the edit form, since there's nothing to view.
function openMoodModal(dateStr){
  editingMoodDate = dateStr;
  const entry = MOOD_ENTRIES.find(e => e.entry_date === dateStr);
  const d = new Date(dateStr + 'T00:00:00');
  document.getElementById('moodModalTitle').textContent = d.toLocaleDateString('en-US',{weekday:'long', month:'long', day:'numeric', year:'numeric'});
  document.getElementById('moodModal').classList.add('open');
  if(entry) renderMoodViewMode(entry);
  else enterMoodEditMode();
}

// The diary's sections, in the order they're written and read. `note` is the
// original single field — kept last as a catch-all so entries written before
// the split still have somewhere to live without being migrated or guessed at.
const MOOD_SECTIONS = [
  { key: 'note_trading', label: 'Trading', icon: '📈' },
  { key: 'note_work',    label: 'Work',    icon: '💼' },
  { key: 'note_life',    label: 'Life',    icon: '🌱' },
  { key: 'note',         label: 'Anything else', icon: '' }
];

function _moodEntryHasText(e){
  return MOOD_SECTIONS.some(s => (e[s.key] || '').trim());
}

function renderMoodViewMode(entry){
  const mood = MOOD_OPTIONS.find(o => o.key === entry.mood);
  document.getElementById('moodViewEmoji').textContent = mood?.emoji || '';
  document.getElementById('moodViewLabel').textContent = mood?.label || entry.mood;
  document.getElementById('moodViewBadge').className = `mood-view-badge mood-view-badge-${mood?.sentiment || 'neutral'}`;
  // Only sections with something in them are shown — empty headings would make
  // a short entry look unfinished.
  const filled = MOOD_SECTIONS.filter(s => (entry[s.key] || '').trim());
  document.getElementById('moodViewNote').innerHTML = filled.length
    ? filled.map(s => `
        <div class="mood-sec">
          <div class="mood-sec-head">${s.icon ? s.icon + ' ' : ''}${s.label}</div>
          <div class="mood-sec-body">${escapeHtml(entry[s.key].trim())}</div>
        </div>`).join('')
    : '<span style="color:var(--muted);">No notes for this day.</span>';
  document.getElementById('moodViewWrap').style.display = 'block';
  document.getElementById('moodEditWrap').style.display = 'none';
}

function enterMoodEditMode(){
  const entry = MOOD_ENTRIES.find(e => e.entry_date === editingMoodDate);
  selectedMoodKey = entry?.mood || null;
  document.getElementById('moodNoteTrading').value = entry?.note_trading || '';
  document.getElementById('moodNoteWork').value = entry?.note_work || '';
  document.getElementById('moodNoteLife').value = entry?.note_life || '';
  document.getElementById('moodNote').value = entry?.note || '';
  document.getElementById('moodModalError').textContent = '';
  renderMoodPicker();
  document.getElementById('moodViewWrap').style.display = 'none';
  document.getElementById('moodEditWrap').style.display = 'block';
}

function closeMoodModal(){
  document.getElementById('moodModal').classList.remove('open');
  editingMoodDate = null;
  selectedMoodKey = null;
}

async function saveMoodEntry(){
  const errEl = document.getElementById('moodModalError');
  errEl.textContent = '';
  if(!selectedMoodKey){ errEl.textContent = 'Please pick how you felt.'; return; }

  const btn = document.getElementById('moodSaveBtn');
  btn.disabled = true;
  btn.textContent = 'Saving…';
  try{
    const res = await fetch(`${SUPABASE_URL}/rest/v1/mood_entries?on_conflict=user_id,entry_date`, {
      method: 'POST',
      headers: {
        "apikey": SUPABASE_KEY,
        "Authorization": `Bearer ${USER_ACCESS_TOKEN}`,
        "Content-Type": "application/json",
        "Prefer": "resolution=merge-duplicates,return=representation"
      },
      body: JSON.stringify([{
        entry_date: editingMoodDate,
        mood: selectedMoodKey,
        note_trading: document.getElementById('moodNoteTrading').value.trim() || null,
        note_work: document.getElementById('moodNoteWork').value.trim() || null,
        note_life: document.getElementById('moodNoteLife').value.trim() || null,
        note: document.getElementById('moodNote').value.trim() || null
      }])
    });
    if(!res.ok) throw new Error(await res.text());
    const rows = await res.json();

    const existingIdx = MOOD_ENTRIES.findIndex(e => e.entry_date === editingMoodDate);
    if(existingIdx >= 0) MOOD_ENTRIES[existingIdx] = rows[0];
    else MOOD_ENTRIES.push(rows[0]);

    closeMoodModal();
    renderMoodCalendar();
    showToast('Mood saved');
  }catch(e){
    console.error("Couldn't save mood entry:", e);
    errEl.textContent = 'Failed to save: ' + (e.message || e);
  }finally{
    btn.disabled = false;
    btn.textContent = 'Save';
  }
}

async function deleteMoodEntry(){
  const existing = MOOD_ENTRIES.find(e => e.entry_date === editingMoodDate);
  if(!existing) return;
  if(!(await customConfirm('Delete this mood entry?', 'Delete'))) return;
  try{
    const res = await fetch(`${SUPABASE_URL}/rest/v1/mood_entries?id=eq.${existing.id}`, {
      method: 'DELETE',
      headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${USER_ACCESS_TOKEN}` }
    });
    if(!res.ok) throw new Error(await res.text());
    MOOD_ENTRIES = MOOD_ENTRIES.filter(e => e.id !== existing.id);
    closeMoodModal();
    renderMoodCalendar();
    showToast('Mood entry deleted');
  }catch(e){
    console.error("Couldn't delete mood entry:", e);
    await customAlert("Couldn't delete — please try again.");
  }
}

/* ---------- Reports (Trading + Finance + Mood recap, with PDF export) ---------- */
let reportPeriodMode = 'this_month';

function onReportPeriodChange(){
  reportPeriodMode = document.getElementById('reportPeriod').value;
  document.getElementById('reportRangeRow').style.display = reportPeriodMode === 'custom' ? 'flex' : 'none';
  renderReportPreview();
}

function _reportStartOfDay(d){ return new Date(d.getFullYear(), d.getMonth(), d.getDate()); }
function _reportEndOfDay(d){ return new Date(d.getFullYear(), d.getMonth(), d.getDate(), 23, 59, 59, 999); }
function _reportDateISO(d){ return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; }

// Resolves the selected dropdown/range into a concrete {start, end, label}
// window — every stat function below just filters against this.
function _reportGetRange(){
  const now = new Date();
  const fmtRange = (start, end) => `${start.toLocaleDateString('en-US',{month:'short',day:'numeric'})} – ${end.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}`;

  if(reportPeriodMode === 'this_week'){
    const monday = new Date(now); monday.setDate(now.getDate() - ((now.getDay() + 6) % 7));
    const start = _reportStartOfDay(monday), end = _reportEndOfDay(now);
    return { start, end, label: fmtRange(start, end) };
  }
  if(reportPeriodMode === 'last_week'){
    const thisMonday = new Date(now); thisMonday.setDate(now.getDate() - ((now.getDay() + 6) % 7));
    const lastMonday = new Date(thisMonday); lastMonday.setDate(thisMonday.getDate() - 7);
    const lastSunday = new Date(thisMonday); lastSunday.setDate(thisMonday.getDate() - 1);
    const start = _reportStartOfDay(lastMonday), end = _reportEndOfDay(lastSunday);
    return { start, end, label: fmtRange(start, end) };
  }
  if(reportPeriodMode === 'last_month'){
    const start = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    const end = new Date(now.getFullYear(), now.getMonth(), 0, 23, 59, 59, 999);
    return { start, end, label: start.toLocaleDateString('en-US',{month:'long',year:'numeric'}) };
  }
  if(reportPeriodMode === 'custom'){
    const fromVal = document.getElementById('reportRangeFrom').value;
    const toVal = document.getElementById('reportRangeTo').value;
    const start = fromVal ? _reportStartOfDay(new Date(fromVal + 'T00:00:00')) : _reportStartOfDay(now);
    const end = toVal ? _reportEndOfDay(new Date(toVal + 'T00:00:00')) : _reportEndOfDay(now);
    return { start, end, label: fmtRange(start, end) };
  }
  // this_month (default)
  const start = new Date(now.getFullYear(), now.getMonth(), 1);
  const end = _reportEndOfDay(now);
  return { start, end, label: now.toLocaleDateString('en-US',{month:'long',year:'numeric'}) };
}

// Whatever currency most of the period's own transactions are in. The old
// version took FIN_ACCOUNTS[0].currency — whichever account happened to load
// first — so the figures could be labelled AED while being mostly PHP.
function _reportPrimaryCurrency(txns){
  if(Array.isArray(txns) && txns.length) return _finPrimaryCurrencyForTxns(txns);
  return FIN_ACCOUNTS[0]?.currency || 'PHP';
}

function _reportTradingStats(start, end){
  const trades = ALL_TRADES.filter(t => t.close_date && t.close_date >= start && t.close_date <= end);
  const total = trades.length;
  // netPnl, not the gross profit_loss: a trade that made $5 and paid $8 in
  // fees is not a win. And breakevens leave the denominator entirely — they're
  // neither won nor lost, and counting them as losses drags the rate down.
  const wins = trades.filter(t => (t.win_loss||'').toLowerCase() === 'win' && netPnl(t) > 0).length;
  const decided = trades.filter(t => ['win','loss','liquidated'].includes((t.win_loss||'').toLowerCase())).length;
  const totalPnl = trades.reduce((s,t) => s + netPnl(t), 0);
  const winRate = decided ? Math.round(wins/decided*100) : 0;
  const rrVals = trades.map(t => t.rr).filter(v => v !== null && !isNaN(v));
  const avgRR = rrVals.length ? (rrVals.reduce((s,v)=>s+v,0)/rrVals.length) : null;
  let bestTrade = null, worstTrade = null;
  trades.forEach(t => {
    if(!bestTrade || netPnl(t) > netPnl(bestTrade)) bestTrade = t;
    if(!worstTrade || netPnl(t) < netPnl(worstTrade)) worstTrade = t;
  });
  return { total, wins, totalPnl, winRate, avgRR, bestTrade, worstTrade, trades };
}

function _reportFinanceStats(start, end){
  const inPeriod = FIN_TXNS.filter(t => t.tx_date && new Date(t.tx_date + 'T00:00:00') >= start && new Date(t.tx_date + 'T00:00:00') <= end);
  // Transfers move money between your own accounts — they're neither income
  // nor expense, and counting them made the section render for a period that
  // had nothing but transfers in it, showing 0 / 0 / 0.
  const real = inPeriod.filter(t => t.tx_type !== 'Transfer');
  const currency = _reportPrimaryCurrency(real);
  // ONE currency only. Adding 500 dirhams to 500 pesos as bare numbers gives
  // 1000 of nothing, and the total was then labelled with a single currency
  // symbol as though it meant something. Same fix as the Discipline radar.
  const txns = real.filter(t => _finTxCurrency(t) === currency);
  const skipped = real.length - txns.length;

  const income = txns.filter(t => t.tx_type === 'Income').reduce((s,t) => s + (Number(t.amount)||0), 0);
  const expense = txns.filter(t => t.tx_type === 'Expense').reduce((s,t) => s + (Number(t.amount)||0), 0);
  const byCat = {};
  txns.filter(t => t.tx_type === 'Expense' && t.category).forEach(t => { byCat[t.category] = (byCat[t.category]||0) + (Number(t.amount)||0); });
  const topCatEntries = Object.entries(byCat).sort((a,b) => b[1]-a[1]);
  const topCategory = topCatEntries.length ? { name: topCatEntries[0][0], amount: topCatEntries[0][1] } : null;
  return { income, expense, net: income - expense, topCategory, txCount: txns.length, currency, skipped };
}

function _reportMoodStats(start, end){
  const entries = MOOD_ENTRIES.filter(e => e.entry_date && new Date(e.entry_date + 'T00:00:00') >= start && new Date(e.entry_date + 'T00:00:00') <= end);
  const counts = {};
  MOOD_OPTIONS.forEach(o => counts[o.key] = 0);
  entries.forEach(e => { if(counts[e.mood] !== undefined) counts[e.mood]++; });
  const totalDays = Math.max(1, Math.round((end - start) / 86400000) + 1);
  return { entries, counts, loggedDays: entries.length, totalDays };
}

// Average trading P&L on days carrying each logged mood — only moods with
// at least one matching trading day are included, sorted best to worst.
function _reportMoodPnlBreakdown(tradingStats, moodStats){
  const byMood = {};
  moodStats.entries.forEach(e => {
    const dayTrades = tradingStats.trades.filter(t => t.close_date && _reportDateISO(t.close_date) === e.entry_date);
    if(!dayTrades.length) return;
    const dayPnl = dayTrades.reduce((s,t) => s + netPnl(t), 0);
    if(!byMood[e.mood]) byMood[e.mood] = { sum: 0, days: 0 };
    byMood[e.mood].sum += dayPnl;
    byMood[e.mood].days += 1;
  });
  return Object.entries(byMood)
    .map(([mood, v]) => ({ mood, avg: v.sum / v.days, days: v.days }))
    .sort((a,b) => b.avg - a.avg);
}

// Structured (not pre-formatted) so both the on-screen preview and the PDF
// can render it in their own markup without duplicating the comparison logic.
function _reportMoodInsightData(moodPnl){
  if(moodPnl.length < 2) return null;
  const best = moodPnl[0], worst = moodPnl[moodPnl.length - 1];
  if(best.avg <= worst.avg) return null;
  const bestOpt = MOOD_OPTIONS.find(o => o.key === best.mood);
  const worstOpt = MOOD_OPTIONS.find(o => o.key === worst.mood);
  return {
    bestLabel: bestOpt?.label || best.mood, bestAvg: best.avg, bestDays: best.days,
    worstLabel: worstOpt?.label || worst.mood, worstAvg: worst.avg, worstDays: worst.days
  };
}

function renderReportPreview(){
  const wrap = document.getElementById('reportPreview');
  if(!wrap) return;
  const { start, end, label } = _reportGetRange();
  document.getElementById('reportPeriodLabel').textContent = label;

  const trading = _reportTradingStats(start, end);
  const finance = _reportFinanceStats(start, end);
  const mood = _reportMoodStats(start, end);
  const insight = _reportMoodInsightData(_reportMoodPnlBreakdown(trading, mood));
  const cur = finance.currency;

  wrap.innerHTML = `
    <div class="report-section">
      <div class="report-section-title">Trading</div>
      ${trading.total ? `
        <div class="kpi-grid" style="margin-bottom:0;">
          <div class="kpi"><div class="label">Trades</div><div class="value">${trading.total}</div></div>
          <div class="kpi"><div class="label">Win Rate</div><div class="value">${trading.winRate}%</div></div>
          <div class="kpi"><div class="label">Total P&L</div><div class="value ${trading.totalPnl>=0?'pos':'neg'}">${fmtMoney(trading.totalPnl)}</div></div>
          <div class="kpi"><div class="label">Avg R:R</div><div class="value">${trading.avgRR!=null ? trading.avgRR.toFixed(2) : '—'}</div></div>
        </div>
        <div style="margin-top:14px;font-size:12.5px;color:var(--muted);">
          Best trade: <span class="pos" style="font-weight:600;">${trading.bestTrade ? fmtMoney(netPnl(trading.bestTrade)) : '—'}</span> (${escapeHtml(trading.bestTrade?.symbol || '—')})
          &nbsp;·&nbsp; Worst trade: <span class="neg" style="font-weight:600;">${trading.worstTrade ? fmtMoney(netPnl(trading.worstTrade)) : '—'}</span> (${escapeHtml(trading.worstTrade?.symbol || '—')})
        </div>
      ` : `<div class="report-empty">No trades in this period.</div>`}
    </div>

    <div class="report-section">
      <div class="report-section-title">Finance</div>
      ${finance.txCount ? `
        <div class="kpi-grid" style="margin-bottom:0;">
          <div class="kpi"><div class="label">Income</div><div class="value pos">${finMoney(finance.income, cur)}</div></div>
          <div class="kpi"><div class="label">Expense</div><div class="value neg">${finMoney(finance.expense, cur)}</div></div>
          <div class="kpi"><div class="label">Net</div><div class="value ${finance.net>=0?'pos':'neg'}">${finMoney(finance.net, cur)}</div></div>
        </div>
        ${finance.topCategory ? `<div style="margin-top:14px;font-size:12.5px;color:var(--muted);">Top category: <span style="color:var(--ink);font-weight:600;">${escapeHtml(finance.topCategory.name)}</span> — ${finMoney(finance.topCategory.amount, cur)}</div>` : ''}
        ${finance.skipped ? `<div style="margin-top:8px;font-size:11.5px;color:var(--muted);">${finance.skipped} transaction${finance.skipped===1?'':'s'} in another currency ${finance.skipped===1?'is':'are'} left out — mixing currencies in one total would make it meaningless.</div>` : ''}
      ` : `<div class="report-empty">No ${cur} income or expenses in this period.</div>`}
    </div>

    <div class="report-section">
      <div class="report-section-title">Mood &amp; Discipline</div>
      ${mood.loggedDays ? `
        <div style="font-size:12.5px;color:var(--muted);margin-bottom:12px;">Logged ${mood.loggedDays} of ${mood.totalDays} days</div>
        <div class="report-mood-bars">
          ${MOOD_OPTIONS.filter(o => mood.counts[o.key] > 0).map(o => {
            const count = mood.counts[o.key];
            const pct = mood.loggedDays ? Math.round(count/mood.loggedDays*100) : 0;
            return `<div class="report-mood-row">
              <span class="report-mood-emoji">${o.emoji}</span>
              <span class="report-mood-label">${escapeHtml(o.label)}</span>
              <div class="report-mood-track"><div class="report-mood-fill" style="width:${pct}%;"></div></div>
              <span class="report-mood-count">${count}</span>
            </div>`;
          }).join('')}
        </div>
      ` : `<div class="report-empty">No mood entries in this period.</div>`}
    </div>

    ${insight ? `
      <div class="report-section">
        <div class="report-section-title">Insight</div>
        <div class="report-insight">On days you logged feeling <b>${escapeHtml(insight.bestLabel)}</b>, your average trading result was <b>${fmtMoney(insight.bestAvg)}</b> (${insight.bestDays} day${insight.bestDays>1?'s':''}). On <b>${escapeHtml(insight.worstLabel)}</b> days, it was <b>${fmtMoney(insight.worstAvg)}</b> (${insight.worstDays} day${insight.worstDays>1?'s':''}).</div>
      </div>
    ` : ''}
  `;
}

// ---- PDF export ----
function downloadReportPDF(){
  if(!window.jspdf){ showToast("PDF library didn't load — check your connection and try again."); return; }
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: 'pt', format: 'a4' });
  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();
  const margin = 44;
  let y = 56;

  // Light-theme palette (a PDF is a white page, so this uses the app's
  // light-mode tokens rather than the dark UI's neon-on-black values).
  const ACCENT = [214, 158, 46], INK = [28, 32, 39], MUTED = [107, 113, 120],
        WIN = [22, 163, 74], LOSS = [229, 62, 62], RULE = [226, 221, 209],
        TINT = [247, 240, 220];

  const { start, end, label } = _reportGetRange();
  const trading = _reportTradingStats(start, end);
  const finance = _reportFinanceStats(start, end);
  const mood = _reportMoodStats(start, end);
  const insight = _reportMoodInsightData(_reportMoodPnlBreakdown(trading, mood));
  const cur = finance.currency;

  function ensureSpace(needed){
    if(y + needed > pageHeight - 50){ doc.addPage(); y = 56; }
  }

  function sectionTitle(text){
    ensureSpace(40);
    doc.setFont('helvetica', 'bold'); doc.setFontSize(12); doc.setTextColor(...ACCENT);
    doc.text(text.toUpperCase(), margin, y);
    y += 6;
    doc.setDrawColor(...RULE); doc.setLineWidth(1);
    doc.line(margin, y, pageWidth - margin, y);
    y += 22;
  }

  function statRow(items){
    ensureSpace(44);
    const colWidth = (pageWidth - margin*2) / items.length;
    items.forEach((item, i) => {
      const x = margin + i*colWidth;
      doc.setFont('helvetica', 'normal'); doc.setFontSize(8.5); doc.setTextColor(...MUTED);
      doc.text(item.label.toUpperCase(), x, y);
      doc.setFont('helvetica', 'bold'); doc.setFontSize(15); doc.setTextColor(...(item.color || INK));
      doc.text(item.value, x, y + 18);
    });
    y += 42;
  }

  function noteLine(text){
    ensureSpace(20);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(9.5); doc.setTextColor(...MUTED);
    doc.text(text, margin, y);
    y += 26;
  }

  function emptyLine(text){
    ensureSpace(24);
    doc.setFont('helvetica', 'italic'); doc.setFontSize(10); doc.setTextColor(...MUTED);
    doc.text(text, margin, y);
    y += 26;
  }

  // Header
  doc.setFont('helvetica', 'bold'); doc.setFontSize(20); doc.setTextColor(...INK);
  doc.text('TANAYDANA', margin, y);
  doc.setFont('helvetica', 'normal'); doc.setFontSize(11); doc.setTextColor(...MUTED);
  doc.text('Performance Report', margin, y + 16);
  doc.setFontSize(10);
  doc.text(label, pageWidth - margin, y, { align: 'right' });
  doc.text(`Generated ${new Date().toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}`, pageWidth - margin, y + 14, { align: 'right' });
  y += 36;
  doc.setDrawColor(...RULE); doc.setLineWidth(1.2);
  doc.line(margin, y, pageWidth - margin, y);
  y += 28;

  // Trading
  sectionTitle('Trading');
  if(trading.total){
    statRow([
      { label: 'Trades', value: String(trading.total) },
      { label: 'Win Rate', value: trading.winRate + '%' },
      { label: 'Total P&L', value: fmtMoney(trading.totalPnl), color: trading.totalPnl >= 0 ? WIN : LOSS },
      { label: 'Avg R:R', value: trading.avgRR != null ? trading.avgRR.toFixed(2) : '—' }
    ]);
    noteLine(`Best trade: ${trading.bestTrade ? fmtMoney(netPnl(trading.bestTrade)) : '—'} (${trading.bestTrade?.symbol || '—'})   ·   Worst trade: ${trading.worstTrade ? fmtMoney(netPnl(trading.worstTrade)) : '—'} (${trading.worstTrade?.symbol || '—'})`);
  }else{
    emptyLine('No trades in this period.');
  }

  // Finance
  sectionTitle('Finance');
  if(finance.txCount){
    statRow([
      { label: 'Income', value: finMoney(finance.income, cur), color: WIN },
      { label: 'Expense', value: finMoney(finance.expense, cur), color: LOSS },
      { label: 'Net', value: finMoney(finance.net, cur), color: finance.net >= 0 ? WIN : LOSS }
    ]);
    if(finance.topCategory) noteLine(`Top category: ${finance.topCategory.name} — ${finMoney(finance.topCategory.amount, cur)}`);
  }else{
    emptyLine('No transactions in this period.');
  }

  // Mood
  sectionTitle('Mood & Discipline');
  if(mood.loggedDays){
    noteLine(`Logged ${mood.loggedDays} of ${mood.totalDays} days`);
    y -= 12;
    const barX = margin + 76, barMaxWidth = 220;
    MOOD_OPTIONS.filter(o => mood.counts[o.key] > 0).forEach(o => {
      ensureSpace(18);
      const count = mood.counts[o.key];
      const pct = mood.loggedDays ? count / mood.loggedDays : 0;
      doc.setFont('helvetica', 'normal'); doc.setFontSize(9); doc.setTextColor(...INK);
      doc.text(o.label, margin, y + 6);
      doc.setFillColor(...RULE);
      doc.roundedRect(barX, y, barMaxWidth, 8, 2, 2, 'F');
      doc.setFillColor(...ACCENT);
      doc.roundedRect(barX, y, Math.max(4, barMaxWidth * pct), 8, 2, 2, 'F');
      doc.setTextColor(...MUTED);
      doc.text(String(count), barX + barMaxWidth + 12, y + 6);
      y += 18;
    });
    y += 12;
  }else{
    emptyLine('No mood entries in this period.');
  }

  // Insight
  if(insight){
    sectionTitle('Insight');
    const text = `On days you logged feeling ${insight.bestLabel}, your average trading result was ${fmtMoney(insight.bestAvg)} (${insight.bestDays} day${insight.bestDays>1?'s':''}). On ${insight.worstLabel} days, it was ${fmtMoney(insight.worstAvg)} (${insight.worstDays} day${insight.worstDays>1?'s':''}).`;
    const lines = doc.splitTextToSize(text, pageWidth - margin*2 - 24);
    const boxHeight = lines.length * 14 + 20;
    ensureSpace(boxHeight);
    doc.setFillColor(...TINT);
    doc.rect(margin, y - 14, pageWidth - margin*2, boxHeight, 'F');
    doc.setFont('helvetica', 'normal'); doc.setFontSize(10); doc.setTextColor(...INK);
    doc.text(lines, margin + 12, y);
    y += boxHeight + 10;
  }

  // Footer (every page)
  const pageCount = doc.internal.getNumberOfPages();
  for(let i = 1; i <= pageCount; i++){
    doc.setPage(i);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(8); doc.setTextColor(...MUTED);
    doc.text(`Generated by Tanaydana · Page ${i} of ${pageCount}`, pageWidth/2, pageHeight - 24, { align: 'center' });
  }

  doc.save(`Tanaydana-Report-${label.replace(/[^\w\d]+/g,'-')}.pdf`);
}


/* ============================================================================
   ASK MY DATA — nakahandang tanong na sinasagot mula mismo sa journal.

   Walang modelo ng wika dito, at sinadya iyon. Ang bawat sagot ay kinakalkula
   mula sa mga trade mo, kaya ang bawat numerong lumalabas ay bilang ng isang
   bagay na talagang nangyari. Ang isang LLM ay mas maganda magsalita pero
   kayang gumawa ng numerong mukhang totoo — at sa isang trading journal, ang
   maling numerong kapani-paniwala ay mas masahol pa sa walang sagot.

   Ang bawat tanong ay may sariling run(), at ito ang kontrata:

     { headline, tone, lines[], action, basis }   — may sagot
     { notEnough: 'dahilan' }                     — kulang pa ang datos

   Ang notEnough ay hindi pagkabigo. Ang pinakamadaling paraan para makagawa ng
   nakakaligaw na payo ay ang sagutin ang tanong na walang sapat na trade, kaya
   mas mabuti pang sabihin kung ilan pa ang kulang. */

const ASK_MIN_N = 8;     // ang pinakamaliit na pangkat na pag-uusapan
const ASK_MIN_CELL = 6;  // para sa pinagkrus na hiwa (pattern × session)

/* Ang expectancy — ang inaasahang piso kada trade — ang siyang tunay na sukat,
   hindi ang win rate. Ang 70% na win rate na may maliliit na panalo at malalaking
   talo ay lugi; ang 35% na may 4R na panalo ay kumikita. Halos lahat ng tanong
   dito ay nagtatapos sa numerong ito. */
function _askStats(trades){
  const wins = trades.filter(_isWin).length;
  const losses = trades.filter(_isLoss).length;
  const bes = trades.filter(_isBE).length;
  const net = trades.reduce((s, t) => s + netPnl(t), 0);
  const decided = wins + losses;
  return {
    n: trades.length, wins, losses, bes, net,
    wr: decided ? wins / decided * 100 : null,
    exp: trades.length ? net / trades.length : null,
  };
}

/* Dalawang anyo ng pera, at may kahulugan ang pagkakaiba.

   _askMoney ay laging may sign, dahil ito ay para sa P&L: mahalaga kung ang
   $200 ay kita o lugi, at ang "+" ay nagsasabi niyon nang walang salita.

   _askAmt ay walang sign, dahil ito ay para sa LAKI: isang target, isang agwat,
   ang distansya sa drawdown floor. Ang paggamit ng _askMoney sa mga ito ay
   nagbubunga ng "-$2,451 to go", na parang may utang ka pang $2,451 gayong
   iyon lang naman ang natitira mong abutin. */
const _askMoney = n => (n < 0 ? '-' : '+') + '$' + Math.abs(n)
  .toLocaleString(undefined, { maximumFractionDigits: 0 });
const _askAmt = n => '$' + Math.abs(n)
  .toLocaleString(undefined, { maximumFractionDigits: 0 });
const _askPct = n => n === null ? '—' : fmtNum(n, 0) + '%';

/* Ang mga trade na may sapat na datos para pag-usapan: sarado, may petsa.
   Sinasagot ng lahat ng tanong ang BUONG kasaysayan maliban kung sinasabi ng
   basis na iba — ang mga filter ng dashboard ay para sa panonood, at ang isang
   tanong na nasasagot ng "ang Hulyo lang pala ang tinitingnan mo" ay mapanlinlang. */
function _askUniverse(){
  return ALL_TRADES.filter(t => t.close_date && String(t.win_loss || '').trim());
}

// Pinagsasama-sama ayon sa isang susi, tinatanggal ang blangko at ang maliliit.
function _askGroupBy(trades, keyFn, minN){
  const by = new Map();
  trades.forEach(t => {
    const k = keyFn(t);
    if(!k || k === 'Unspecified' || k === '—') return;
    if(!by.has(k)) by.set(k, []);
    by.get(k).push(t);
  });
  return [...by.entries()]
    .filter(([, arr]) => arr.length >= (minN ?? ASK_MIN_N))
    .map(([k, arr]) => ({ key: k, trades: arr, ...(_askStats(arr)) }));
}

// Ang ika-ilang trade sa loob ng araw, ayon sa oras ng pagbukas. Kailangan ito
// ng dalawang tanong (revenge at kailan titigil), kaya isang beses lang ito.
function _askDayIndex(trades){
  const byDay = new Map();
  trades.forEach(t => {
    const d = t.open_date || t.close_date;
    if(!d) return;
    const k = _dayKeyUTC(new Date(d));
    if(!byDay.has(k)) byDay.set(k, []);
    byDay.get(k).push(t);
  });
  const out = [];
  byDay.forEach(arr => {
    arr.sort((a, b) => (a.open_date || a.close_date) - (b.open_date || b.close_date));
    arr.forEach((t, i) => out.push({ t, idx: i + 1, prev: i ? arr[i - 1] : null }));
  });
  return out;
}

const ASK_GROUPS = [
  { id: 'money',  n: '1', title: 'Money and the goal',
    sub: 'Where the month actually stands, and what to do about it' },
  { id: 'edge',   n: '2', title: 'Is my edge still working',
    sub: 'What is earning, what has stopped, and what to drop' },
  { id: 'habit',  n: '3', title: 'How I behave',
    sub: 'The patterns in how you trade, not in what you trade' },
];

const ASK_QUESTIONS = [

  /* -------------------------------------------------- 1. Money and the goal */
  {
    id: 'month-green', group: 'money',
    q: 'What one change would have made this month green?',
    hint: 'Replays the month with each cause removed and ranks them by what it would have been worth.',
    run(){
      const now = new Date();
      const y = now.getFullYear(), m = now.getMonth();
      const month = _askUniverse().filter(t => {
        const d = t.close_date;
        return d.getFullYear() === y && d.getMonth() === m;
      });
      if(month.length < 5) return { notEnough:
        `Only ${month.length} closed trade${month.length === 1 ? '' : 's'} this month. Ask again once there are at least 5 — before that, one trade moves the whole answer.` };

      const net = month.reduce((s, t) => s + netPnl(t), 0);

      /* Bawat kandidato ay isang tanong na "paano kung wala ito": alisin ang
         lahat ng trade na may katangiang ito at tingnan ang natitirang buwan.
         Hindi ito hula — ang mga trade na iyon ay nangyari, at ito ang totoong
         kabuuan kung wala sila. */
      const cands = [];
      const add = (label, kind, keep) => {
        const without = month.filter(keep);
        if(without.length === month.length) return;      // walang tinanggal
        if(!without.length) return;                      // lahat tatanggalin
        const gain = without.reduce((s, t) => s + netPnl(t), 0) - net;
        if(gain <= 0) return;                            // wala itong naitutulong
        cands.push({ label, kind, gain, removed: month.length - without.length });
      };

      /* Ang unfollowed_rules ay isang STRING na pinagdugtong ng comma, hindi
         array — ang normalizeTrade ay nag-.join(', ') dito. Ang unang sulat ko
         ay Array.isArray(), na laging false, kaya tahimik na WALANG rule ang
         nakita. Ang _brokenRuleTags ang tamang pintuan: ito ang naghahati,
         nagsasalin ng alias, at nagsasala para sa mga tunay na paglabag —
         hindi ang mga obserbasyon, na hindi naman pagkakamali. */
      const tagsOf = t => _brokenRuleTags(t.unfollowed_rules);
      new Set(month.flatMap(tagsOf)).forEach(tag =>
        add(`the trades where you ${tag.toLowerCase()}`, 'rule', t => !tagsOf(t).includes(tag)));
      new Set(month.map(t => t.session).filter(s => s && s !== 'Unspecified')).forEach(s =>
        add(`the ${s} session`, 'session', t => t.session !== s));
      new Set(month.map(t => t.pattern_type).filter(p => p && p !== 'Unspecified')).forEach(p =>
        add(`the ${p} setups`, 'pattern', t => t.pattern_type !== p));

      cands.sort((a, b) => b.gain - a.gain);
      if(!cands.length) return {
        headline: net >= 0 ? 'Nothing was dragging this month down.' : 'No single cause explains this month.',
        tone: net >= 0 ? 'good' : 'flat',
        lines: [`The month is at ${_askMoney(net)} across ${month.length} trades.`,
          net >= 0 ? 'Every group of trades is carrying its weight.'
                   : 'The losses are spread evenly rather than sitting in one setup, session or rule. That usually means sizing or the market, not a leak you can name.'],
        action: net >= 0 ? 'Keep going.' : 'Look at the Breakeven and Invalidation reports instead — the leak is in how you manage trades, not which ones you take.',
        basis: `This month, ${month.length} closed trades.`,
      };

      const top = cands[0];
      return {
        headline: net >= 0
          ? `The month is already green — but dropping ${top.label} would have added ${_askMoney(top.gain)}.`
          : `Dropping ${top.label} alone would have made the month ${_askMoney(net + top.gain)}.`,
        tone: net >= 0 ? 'good' : (net + top.gain >= 0 ? 'warn' : 'bad'),
        lines: [
          `The month stands at ${_askMoney(net)} across ${month.length} trades.`,
          ...cands.slice(0, 3).map(c =>
            `Without ${c.label} — ${c.removed} trade${c.removed === 1 ? '' : 's'} — the month is ${_askMoney(net + c.gain)}, ${_askMoney(c.gain)} better.`),
        ],
        action: top.kind === 'rule'
          ? `The biggest single leak is a rule you are breaking, not a setup that stopped working. That is the cheapest thing on this list to fix.`
          : `Try one month without ${top.label} and compare. If the gap holds, it is real.`,
        basis: `This month, ${month.length} closed trades. Each line is the real total with those trades removed.`,
      };
    },
  },

  {
    id: 'pace', group: 'money',
    q: 'Am I on pace for my salary goal this month?',
    hint: 'Not just the percentage — how many more trades it takes at the size you actually win.',
    run(){
      if(!PROFILE_DATA) return { notEnough: 'Your profile has not loaded yet. Try again in a moment.' };
      const v = _salarySettings();
      const aed = Number(v.aed_per_usd) > 0 ? Number(v.aed_per_usd) : SALARY_DEFAULTS.aed_per_usd;
      const salary = Number(v.monthly_salary);
      if(!Number.isFinite(salary) || salary <= 0)
        return { notEnough: 'No monthly salary is saved. Set it on the Salary vs Trading page and this can answer.' };

      const need = salary / aed;
      const now = new Date();
      const y = now.getFullYear(), m = now.getMonth();
      const month = _askUniverse().filter(t =>
        t.close_date.getFullYear() === y && t.close_date.getMonth() === m);
      const made = month.reduce((s, t) => s + netPnl(t), 0);
      const short = need - made;
      const left = _tradingDaysLeft(y, m, now);

      if(made >= need) return {
        headline: `Goal reached — ${Math.round(made / need * 100)}% of it, with ${left} trading day${left === 1 ? '' : 's'} still to go.`,
        tone: 'good',
        lines: [`You needed ${_askAmt(need)} and you are at ${_askMoney(made)}.`,
          'Everything from here is ahead of the salary, not chasing it.'],
        action: 'The risk now is giving it back. This is the part of the month where size creeps up.',
        basis: `${month.length} closed trades this month against a ${_askAmt(need)} target.`,
      };

      // Ang laki ng panalo ay galing sa BUONG kasaysayan, hindi sa buwang ito:
      // ang isang masamang buwan ay magbibigay ng maliit na average at
      // magmumungkahi ng mas maraming trade kaysa sa totoong kailangan.
      const all = _askUniverse();
      const wins = all.filter(_isWin);
      const avgWin = wins.length ? wins.reduce((s, t) => s + netPnl(t), 0) / wins.length : null;
      const st = _askStats(all);
      const perTrade = st.exp;

      const lines = [`You need ${_askAmt(need)} this month and you are at ${_askMoney(made)} — ${_askAmt(short)} to go.`];
      if(left > 0) lines.push(`That is ${_askAmt(short / left)} a day across the ${left} trading day${left === 1 ? '' : 's'} you have left.`);
      if(avgWin && avgWin > 0)
        lines.push(`Your average win is ${_askMoney(avgWin)}, so that is about ${Math.ceil(short / avgWin)} more winning trades.`);
      if(perTrade && perTrade > 0)
        lines.push(`At your long-run average of ${_askMoney(perTrade)} per trade — wins and losses together — it takes about ${Math.ceil(short / perTrade)} more trades.`);

      let tone = 'warn', action;
      if(perTrade !== null && perTrade <= 0){
        tone = 'bad';
        action = 'Your long-run average per trade is not positive, so more trades will not close this gap. The gap is not a volume problem.';
      }else if(left <= 0){
        tone = 'bad';
        action = 'The month is out of trading days. This one is set — carry the number into next month rather than forcing trades.';
      }else if(perTrade && Math.ceil(short / perTrade) / left > 4){
        tone = 'bad';
        action = `That is more than 4 trades a day every remaining day. Reaching for it is how ${left} days becomes a drawdown — treat the goal as missed and protect the account instead.`;
      }else{
        action = 'The pace is reachable at your normal rate. Nothing here needs bigger size.';
      }
      return { headline: left > 0
          ? `${_askAmt(short)} to go, ${left} trading day${left === 1 ? '' : 's'} left.`
          : `${_askAmt(short)} short, and the month is out of trading days.`,
        tone, lines, action,
        basis: `This month against your saved salary (${fmtNum(salary, 0)} AED ÷ ${fmtNum(aed, 2)}). Trade sizes come from all ${all.length} trades.` };
    },
  },

  {
    id: 'prop-risk', group: 'money',
    q: 'How close am I to breaking a prop firm rule?',
    hint: 'Distance to the drawdown floor, measured in losing trades of the size you actually lose.',
    run(){
      const accs = (TRADING_ACCOUNTS || []).filter(a =>
        a.account_type !== 'Exchange' && Number(a.account_size) > 0);
      if(!accs.length) return { notEnough: 'No prop firm accounts are set up with an account size. Add them on My Accounts.' };

      const all = _askUniverse();
      const losses = all.filter(_isLoss);
      const avgLoss = losses.length
        ? Math.abs(losses.reduce((s, t) => s + netPnl(t), 0) / losses.length) : null;

      const rows = [];
      accs.forEach(a => {
        const s = computeAccountStats(a);
        const room = s.currentBalance - s.drawdownFloor;
        const toGoal = s.profitGoal - s.currentBalance;
        rows.push({ name: a.account_name, room, toGoal,
          trades: (avgLoss && avgLoss > 0) ? Math.floor(room / avgLoss) : null,
          daily: s.dailyLossLimit - s.dailyLossUsed });
      });
      rows.sort((a, b) => (a.trades ?? 1e9) - (b.trades ?? 1e9));
      const worst = rows[0];

      const lines = rows.map(r => {
        const bits = [`${r.name}: ${_askAmt(r.room)} above the floor`];
        if(r.trades !== null) bits.push(`about ${r.trades} more losing trade${r.trades === 1 ? '' : 's'} at your average`);
        if(r.toGoal > 0) bits.push(`${_askAmt(r.toGoal)} from the profit target`);
        return bits.join(' — ') + '.';
      });
      if(avgLoss) lines.push(`Your average loss is ${_askMoney(-avgLoss)} across ${losses.length} losing trades.`);

      const tone = worst.trades === null ? 'flat'
        : worst.trades <= 3 ? 'bad' : worst.trades <= 8 ? 'warn' : 'good';
      return {
        headline: worst.trades === null
          ? 'No losing trades recorded yet, so there is nothing to measure the distance in.'
          : worst.trades <= 3
            ? `${worst.name} is about ${worst.trades} losing trade${worst.trades === 1 ? '' : 's'} from breaching.`
            : `Your tightest account, ${worst.name}, has room for about ${worst.trades} more average losses.`,
        tone, lines,
        action: worst.trades !== null && worst.trades <= 3
          ? 'This is the point where cutting size matters more than finding a setup. A normal losing streak ends this account.'
          : 'Nothing urgent. Worth re-checking after any losing day.',
        basis: `Live account balances against each account's own drawdown rule. Loss size comes from all ${losses.length} losing trades.`,
      };
    },
  },

  {
    id: 'size', group: 'money',
    q: 'Is my risk size consistent — and does size change my results?',
    hint: 'If bigger positions win less often, confidence is pointing the wrong way.',
    run(){
      const all = _askUniverse().filter(t => Number(t.position_size) > 0);
      if(all.length < 3 * ASK_MIN_N) return { notEnough:
        `Only ${all.length} trades have a position size recorded. This needs about ${3 * ASK_MIN_N} to split into sizes worth comparing.` };

      const sorted = [...all].sort((a, b) => Number(a.position_size) - Number(b.position_size));
      const third = Math.floor(sorted.length / 3);
      const small = _askStats(sorted.slice(0, third));
      const big   = _askStats(sorted.slice(-third));
      const sizes = sorted.map(t => Number(t.position_size));
      const med = sizes[Math.floor(sizes.length / 2)];
      const spread = med > 0 ? (sizes[sorted.length - 1 - third] / sizes[third]) : null;

      const gap = (big.wr ?? 0) - (small.wr ?? 0);
      const consistent = spread !== null && spread < 2;

      const lines = [
        `Your smallest third wins ${_askPct(small.wr)} of the time at ${_askMoney(small.exp)} per trade.`,
        `Your largest third wins ${_askPct(big.wr)} at ${_askMoney(big.exp)} per trade.`,
        spread !== null
          ? `Typical size is ${fmtNum(med, 3)}, and your big trades are about ${fmtNum(spread, 1)}× your small ones.`
          : '',
      ].filter(Boolean);

      let tone, headline, action;
      if(gap < -8){
        tone = 'bad';
        headline = `You win ${_askPct(Math.abs(gap))} LESS often on your biggest trades.`;
        action = 'Whatever makes you size up is not a real signal. Trading one flat size would have earned more than sizing on conviction.';
      }else if(gap > 8){
        tone = 'good';
        headline = `Your biggest trades also win most often — ${_askPct(Math.abs(gap))} more than your smallest.`;
        action = 'Your conviction is genuinely informative. The risk is the day it is wrong and the size is on.';
      }else{
        tone = consistent ? 'good' : 'warn';
        headline = consistent
          ? 'Your size is consistent, and size is not changing your results.'
          : 'Your size varies a lot, but it is not changing your results.';
        action = consistent
          ? 'Nothing to fix here.'
          : 'Since bigger size does not win more, the variation is adding swing without adding return. One flat size would be calmer for the same money.';
      }
      return { headline, tone, lines, action,
        basis: `${all.length} trades with a position size, split into thirds by size.` };
    },
  },

  /* --------------------------------------------------- 2. Is my edge working */
  {
    id: 'drift', group: 'edge',
    q: 'Has my edge changed in the last 30 days?',
    hint: 'The earliest warning that something broke — and whether the drop is real or ordinary variance.',
    run(){
      const all = _askUniverse();
      const cut = new Date(Date.now() - 30 * 864e5);
      const recent = all.filter(t => t.close_date >= cut);
      const before = all.filter(t => t.close_date < cut);
      if(recent.length < ASK_MIN_N) return { notEnough:
        `Only ${recent.length} closed trades in the last 30 days. This needs ${ASK_MIN_N}.` };
      if(before.length < ASK_MIN_N) return { notEnough:
        `Only ${before.length} trades before the last 30 days, so there is no baseline to compare against yet.` };

      const r = _askStats(recent), b = _askStats(before);
      const wrGap = (r.wr ?? 0) - (b.wr ?? 0);
      const expGap = (r.exp ?? 0) - (b.exp ?? 0);

      /* Kailan tunay ang pagbagsak? Ang win rate sa maliit na bilang ay
         natural na tumataas-bumaba. Ang magaspang pero tapat na panukat ay ang
         standard error ng baseline: kung ang agwat ay wala pang dalawang beses
         nito, hindi pa ito mapaghihiwalay sa malas. */
      const p = (b.wr ?? 0) / 100;
      const se = r.n > 0 ? Math.sqrt(Math.max(p * (1 - p), 0.01) / r.n) * 100 : 99;
      const real = Math.abs(wrGap) > 2 * se;

      const lines = [
        `Last 30 days: ${r.n} trades, ${_askPct(r.wr)} win rate, ${_askMoney(r.exp)} per trade.`,
        `Before that: ${b.n} trades, ${_askPct(b.wr)} win rate, ${_askMoney(b.exp)} per trade.`,
        real
          ? `A swing this size is bigger than ordinary variance at ${r.n} trades — it is unlikely to be luck.`
          : `A swing this size is within ordinary variance at ${r.n} trades. It is too early to call it a change.`,
      ];

      let tone, headline, action;
      if(!real){
        tone = 'flat';
        headline = 'Nothing has measurably changed.';
        action = 'Keep trading the same way. Re-check after another 10–15 trades.';
      }else if(wrGap < 0 || expGap < 0){
        tone = 'bad';
        headline = `Your edge has genuinely dropped — ${_askPct(Math.abs(wrGap))} lower win rate than your baseline.`;
        action = 'Cut size first, then find out which setup changed — ask "which setup should I stop trading" next.';
      }else{
        tone = 'good';
        headline = `You are trading measurably better than your baseline — ${_askPct(wrGap)} higher.`;
        action = 'Worth finding out what changed so it is repeatable rather than a good run.';
      }
      return { headline, tone, lines, action,
        basis: `Last 30 days (${r.n} trades) against everything before it (${b.n} trades).` };
    },
  },

  {
    id: 'combo', group: 'edge',
    q: 'What is my most profitable combination?',
    hint: 'Pattern crossed with session. Your panels look at one dimension at a time; the edge usually lives in the crossing.',
    run(){
      const all = _askUniverse();
      const cells = _askGroupBy(all,
        t => (t.pattern_type && t.pattern_type !== 'Unspecified' &&
              t.session && t.session !== 'Unspecified')
          ? `${t.pattern_type} · ${t.session}` : null,
        ASK_MIN_CELL);
      if(!cells.length) return { notEnough:
        `No pattern-and-session combination has ${ASK_MIN_CELL} trades yet. Keep logging both fields and this fills in.` };

      const base = _askStats(all);
      cells.sort((a, b) => (b.exp ?? -1e9) - (a.exp ?? -1e9));
      const best = cells[0], worst = cells[cells.length - 1];

      const lines = cells.slice(0, 4).map(c =>
        `${c.key} — ${c.n} trades, ${_askPct(c.wr)} win rate, ${_askMoney(c.exp)} per trade.`);
      lines.push(`Your overall average is ${_askMoney(base.exp)} per trade across ${base.n} trades.`);
      if(cells.length > 1 && worst.exp < 0)
        lines.push(`The weakest combination is ${worst.key} at ${_askMoney(worst.exp)} per trade over ${worst.n} trades.`);

      const edge = (best.exp ?? 0) - (base.exp ?? 0);
      return {
        headline: `${best.key} is your best combination — ${_askMoney(best.exp)} per trade against your ${_askMoney(base.exp)} average.`,
        tone: best.exp > 0 ? 'good' : 'warn',
        lines,
        action: best.n < 15
          ? `Only ${best.n} trades, so treat this as a lead rather than a conclusion. Keep taking it and re-check.`
          : (edge > 0
            ? `That is ${_askMoney(edge)} per trade better than your average. Taking more of these and fewer of everything else is the simplest change on this whole list.`
            : 'Even your best combination is not beating your average, which means the edge is not in what you pick.'),
        basis: `All ${all.length} closed trades, grouped by pattern × session, minimum ${ASK_MIN_CELL} trades per combination.`,
      };
    },
  },

  {
    id: 'stop-setup', group: 'edge',
    q: 'Which setup should I stop trading?',
    hint: 'The worst performer that has enough trades behind it to not just be a bad run.',
    run(){
      const all = _askUniverse();
      const pats = _askGroupBy(all, t => t.pattern_type);
      if(!pats.length) return { notEnough:
        `No setup has ${ASK_MIN_N} trades yet. This needs a bit more history before it can name one.` };

      const base = _askStats(all);
      pats.sort((a, b) => (a.exp ?? 1e9) - (b.exp ?? 1e9));
      const worst = pats[0];

      const lines = pats.map(p =>
        `${p.key} — ${p.n} trades, ${_askPct(p.wr)} win rate, ${_askMoney(p.exp)} per trade, ${_askMoney(p.net)} total.`);

      if(worst.exp >= 0) return {
        headline: 'Nothing needs dropping — every setup with enough history is making money.',
        tone: 'good', lines,
        action: 'The weakest is ' + worst.key + ', but it is still positive. Leave it.',
        basis: `All ${all.length} closed trades, minimum ${ASK_MIN_N} per setup.`,
      };

      // Ano ang halaga ng pagtigil? Ang kabuuan lang nito — hindi hula.
      return {
        headline: `${worst.key} — it has cost you ${_askMoney(worst.net)} across ${worst.n} trades.`,
        tone: 'bad', lines,
        action: `Not taking a single ${worst.key} trade would have left you ${_askMoney(-worst.net)} better off, with no other change. That is the cheapest improvement available to you.`,
        basis: `All ${all.length} closed trades, minimum ${ASK_MIN_N} per setup. Your overall average is ${_askMoney(base.exp)} per trade.`,
      };
    },
  },

  {
    id: 'best-setup', group: 'edge',
    q: 'What is my best setup, and is it still working?',
    hint: 'Names the setup, then checks the last 30 days against its own history.',
    run(){
      const all = _askUniverse();
      const pats = _askGroupBy(all, t => t.pattern_type);
      if(!pats.length) return { notEnough:
        `No setup has ${ASK_MIN_N} trades yet.` };

      pats.sort((a, b) => (b.exp ?? -1e9) - (a.exp ?? -1e9));
      const best = pats[0];

      const cut = new Date(Date.now() - 30 * 864e5);
      const recent = _askStats(best.trades.filter(t => t.close_date >= cut));
      const lines = [
        `${best.key} — ${best.n} trades, ${_askPct(best.wr)} win rate, ${_askMoney(best.exp)} per trade, ${_askMoney(best.net)} total.`,
      ];
      if(pats[1]) lines.push(`Next best is ${pats[1].key} at ${_askMoney(pats[1].exp)} per trade.`);

      let still = null;
      if(recent.n >= 4){
        lines.push(`In the last 30 days it has run ${recent.n} times at ${_askPct(recent.wr)} and ${_askMoney(recent.exp)} per trade.`);
        still = recent.exp >= 0;
      }else{
        lines.push(`It has only run ${recent.n} time${recent.n === 1 ? '' : 's'} in the last 30 days — not enough to say whether it is still working.`);
      }

      return {
        headline: `${best.key}, at ${_askMoney(best.exp)} per trade.`,
        tone: still === false ? 'warn' : 'good', lines,
        action: still === false
          ? `It is your best setup overall but it is not earning right now. Keep taking it at reduced size and re-check in two weeks rather than dropping it on ${recent.n} trades.`
          : (still === true
            ? 'Still earning. This is the one to take more of when you are choosing between setups.'
            : 'Take it when it appears — there is not enough recent history to say more than that.'),
        basis: `All ${all.length} closed trades, minimum ${ASK_MIN_N} per setup.`,
      };
    },
  },

  /* ------------------------------------------------------ 3. How I behave */
  {
    id: 'after-loss', group: 'habit',
    q: 'Do I trade worse after a loss?',
    hint: 'The trade straight after a red one, on the same day. This is where revenge trading shows up.',
    run(){
      const idx = _askDayIndex(_askUniverse());
      const afterLoss = idx.filter(x => x.prev && _isLoss(x.prev)).map(x => x.t);
      const afterWin  = idx.filter(x => x.prev && _isWin(x.prev)).map(x => x.t);
      if(afterLoss.length < ASK_MIN_N) return { notEnough:
        `Only ${afterLoss.length} trades follow a loss on the same day. This needs ${ASK_MIN_N}.` };
      if(afterWin.length < 4) return { notEnough:
        `Only ${afterWin.length} trades follow a win on the same day, so there is nothing fair to compare against.` };

      const L = _askStats(afterLoss), W = _askStats(afterWin);
      const base = _askStats(_askUniverse());
      const gap = (L.wr ?? 0) - (W.wr ?? 0);

      const lines = [
        `After a loss: ${L.n} trades, ${_askPct(L.wr)} win rate, ${_askMoney(L.exp)} per trade, ${_askMoney(L.net)} total.`,
        `After a win: ${W.n} trades, ${_askPct(W.wr)} win rate, ${_askMoney(W.exp)} per trade.`,
        `Your overall average is ${_askPct(base.wr)} and ${_askMoney(base.exp)} per trade.`,
      ];

      if(gap < -8 || (L.exp !== null && L.exp < 0 && base.exp > 0)){
        return {
          headline: `Yes — after a loss you win ${_askPct(Math.abs(gap))} less often, and those trades have cost you ${_askMoney(L.net)}.`,
          tone: 'bad', lines,
          action: 'The rule that follows from this is simple and testable: no trade for 30 minutes after a red one. Everything else on this page is about what to trade; this is about when to stop.',
          basis: `${L.n + W.n} same-day follow-up trades out of ${base.n} closed trades.`,
        };
      }
      if(gap > 8) return {
        headline: `No — you actually trade BETTER after a loss, by ${_askPct(gap)}.`,
        tone: 'good', lines,
        action: 'Losses sharpen you rather than tilt you. Nothing to fix, and worth knowing about yourself.',
        basis: `${L.n + W.n} same-day follow-up trades.`,
      };
      return {
        headline: 'No — a loss does not change how you trade next.',
        tone: 'good', lines,
        action: 'This is the discipline problem you do not have. Spend the effort somewhere else on this list.',
        basis: `${L.n + W.n} same-day follow-up trades.`,
      };
    },
  },

  {
    id: 'stop-for-day', group: 'habit',
    q: 'When should I stop trading for the day?',
    hint: 'Win rate by how deep into the day you are. A clear cliff here is a rule you can actually follow.',
    run(){
      const idx = _askDayIndex(_askUniverse());
      if(idx.length < 3 * ASK_MIN_N) return { notEnough:
        `Only ${idx.length} trades have an open time to order the day by. This needs about ${3 * ASK_MIN_N}.` };

      const bucket = n => n >= 4 ? '4th or later' : ['1st', '2nd', '3rd'][n - 1];
      const groups = _askGroupBy(idx.map(x => ({ ...x.t, _b: bucket(x.idx) })), t => t._b, 4);
      const order = ['1st', '2nd', '3rd', '4th or later'];
      groups.sort((a, b) => order.indexOf(a.key) - order.indexOf(b.key));
      if(groups.length < 2) return { notEnough: 'Almost every day is a single trade, so there is no "later in the day" to compare.' };

      const lines = groups.map(g =>
        `${g.key} trade of the day — ${g.n} trades, ${_askPct(g.wr)} win rate, ${_askMoney(g.exp)} per trade, ${_askMoney(g.net)} total.`);

      // Ang unang pangkat na palugi, at lahat ng pagkatapos nito, ang hangganan.
      const firstBad = groups.findIndex(g => (g.exp ?? 0) < 0);
      if(firstBad <= 0){
        const worst = [...groups].sort((a, b) => (a.exp ?? 0) - (b.exp ?? 0))[0];
        return {
          headline: 'No cut-off shows up — you do not get worse as the day goes on.',
          tone: 'good', lines,
          action: `Your weakest slot is the ${worst.key} trade at ${_askMoney(worst.exp)} per trade, but it is still not losing. Trade count is not your problem.`,
          basis: `${idx.length} trades ordered by open time within each day.`,
        };
      }
      const after = groups.slice(firstBad);
      const cost = after.reduce((s, g) => s + g.net, 0);
      const count = after.reduce((s, g) => s + g.n, 0);
      return {
        headline: `Stop after the ${groups[firstBad - 1].key} trade — everything past it has cost you ${_askMoney(cost)}.`,
        tone: 'bad', lines,
        action: `Those ${count} trades are ${_askMoney(cost)} of your total. A hard cap at ${firstBad} trade${firstBad === 1 ? '' : 's'} a day changes nothing else about how you trade and keeps that money.`,
        basis: `${idx.length} trades ordered by open time within each day.`,
      };
    },
  },

  {
    id: 'costly-rule', group: 'habit',
    q: 'Which rule costs me the most money?',
    hint: 'Not the one you break most often — the one that does the most damage when you do.',
    run(){
      const all = _askUniverse();
      const tagsOf = t => _brokenRuleTags(t.unfollowed_rules);
      const tagged = all.filter(t => tagsOf(t).length);
      if(tagged.length < ASK_MIN_N) return { notEnough:
        `Only ${tagged.length} trades have a broken-rule tag on them. Tag a few more in the drawer and this can answer.` };

      /* Ang paghahambing ay laban sa mga trade na TINATAKAN mong malinis, hindi
         sa lahat ng walang tatak. Ang walang tatak ay "hindi naitala", at
         maaaring may paglabag na hindi lang naisulat — kung isasama iyon sa
         baseline, ang mismong pinsalang sinusukat natin ay makakapasok dito at
         magpapaliit ng bawat gastos. */
      const clean = all.filter(t => _isCleanRules(t.unfollowed_rules));
      const baseExp = clean.length >= 5 ? _askStats(clean).exp : _askStats(all).exp;

      const rows = [];
      new Set(all.flatMap(tagsOf)).forEach(tag => {
        const arr = all.filter(t => tagsOf(t).includes(tag));
        if(arr.length < 3) return;
        const s = _askStats(arr);
        // Ang gastos ay ang AGWAT sa iyong malinis na trade, hindi ang kabuuan.
        // Ang isang tag na nasa mga panalo lang ay may positibong kabuuan pero
        // maaari pa ring mas malala kaysa sa karaniwan mong trade.
        rows.push({ tag, ...s, cost: ((baseExp ?? 0) - (s.exp ?? 0)) * s.n });
      });
      if(!rows.length) return { notEnough: 'No rule tag appears on 3 or more trades yet.' };

      rows.sort((a, b) => b.cost - a.cost);
      const top = rows[0];
      const lines = rows.slice(0, 5).map(r =>
        `${r.tag} — ${r.n} times, ${_askPct(r.wr)} win rate, ${_askMoney(r.exp)} per trade` +
        (r.cost > 0 ? `, about ${_askMoney(-r.cost)} worse than your clean trades.` : `, no worse than your clean trades.`));
      lines.push(clean.length >= 5
        ? `Your trades tagged clean average ${_askMoney(baseExp)} each across ${clean.length} trades.`
        : `Too few trades are tagged clean, so this compares against your overall average of ${_askMoney(baseExp)}.`);

      if(top.cost <= 0) return {
        headline: 'None of your tagged rules is measurably costing you money.',
        tone: 'good', lines,
        action: 'Either the tags are not where the damage is, or you are tagging the trades that happened to work out. The Discipline reports are the better place to look next.',
        basis: `${tagged.length} trades with a broken rule out of ${all.length}.`,
      };
      return {
        headline: `${top.tag} — about ${_askMoney(-top.cost)} worse than trading clean, across ${top.n} trades.`,
        tone: 'bad', lines,
        action: `Frequency is not the point: ${top.tag} is the one that does the damage when it happens. Fixing this one rule is worth more than fixing the other ${rows.length - 1} put together in most months.`,
        basis: `${tagged.length} trades with a broken rule out of ${all.length}. Cost is the gap against your ${clean.length >= 5 ? 'clean-tagged' : 'overall'} average, times how often it happened.`,
      };
    },
  },

  {
    id: 'best-time', group: 'habit',
    q: 'What day and hour am I actually best at?',
    hint: 'Session is eight hours wide — too coarse to act on. This is the hour you opened the trade.',
    run(){
      const all = _askUniverse().filter(t => t.open_date);
      if(all.length < 3 * ASK_MIN_N) return { notEnough:
        `Only ${all.length} trades have an open time. This needs about ${3 * ASK_MIN_N}.` };

      const DAY = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
      const hourLabel = h => {
        const ampm = h < 12 ? 'am' : 'pm';
        const hh = h % 12 === 0 ? 12 : h % 12;
        return `${hh}${ampm}`;
      };
      // Oras ng UAE — doon siya nakaupo, at ang UTC ay walang kahulugan
      // sa isang bagay na dapat sundin sa totoong buhay.
      const uaeParts = d => {
        const p = new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Dubai',
          weekday: 'long', hour: 'numeric', hour12: false }).formatToParts(d);
        return { day: p.find(x => x.type === 'weekday')?.value,
                 hour: Number(p.find(x => x.type === 'hour')?.value) };
      };

      const days  = _askGroupBy(all, t => uaeParts(t.open_date).day);
      const hours = _askGroupBy(all, t => {
        const h = uaeParts(t.open_date).hour;
        return Number.isFinite(h) ? String(h).padStart(2, '0') : null;
      });
      if(!days.length && !hours.length) return { notEnough:
        `No day or hour has ${ASK_MIN_N} trades yet.` };

      const base = _askStats(all);
      const byExp = a => [...a].sort((x, y) => (y.exp ?? -1e9) - (x.exp ?? -1e9));
      const bd = byExp(days), bh = byExp(hours);
      const lines = [];
      if(bd.length){
        lines.push(`Best day: ${bd[0].key} — ${bd[0].n} trades, ${_askPct(bd[0].wr)}, ${_askMoney(bd[0].exp)} per trade.`);
        if(bd.length > 1) lines.push(`Worst day: ${bd[bd.length-1].key} — ${bd[bd.length-1].n} trades, ${_askPct(bd[bd.length-1].wr)}, ${_askMoney(bd[bd.length-1].exp)} per trade.`);
      }
      if(bh.length){
        lines.push(`Best hour: ${hourLabel(+bh[0].key)} UAE — ${bh[0].n} trades, ${_askPct(bh[0].wr)}, ${_askMoney(bh[0].exp)} per trade.`);
        if(bh.length > 1) lines.push(`Worst hour: ${hourLabel(+bh[bh.length-1].key)} UAE — ${bh[bh.length-1].n} trades, ${_askPct(bh[bh.length-1].wr)}, ${_askMoney(bh[bh.length-1].exp)} per trade.`);
      }
      lines.push(`Your overall average is ${_askMoney(base.exp)} per trade.`);

      const worstDay = bd.length > 1 ? bd[bd.length - 1] : null;
      const headline = bd.length && bh.length
        ? `${bd[0].key} around ${hourLabel(+bh[0].key)} UAE time.`
        : (bd.length ? `${bd[0].key}.` : `${hourLabel(+bh[0].key)} UAE time.`);
      return {
        headline, tone: 'good', lines,
        action: worstDay && worstDay.net < 0
          ? `Not trading ${worstDay.key} at all would have saved you ${_askMoney(-worstDay.net)}, with nothing else changed.`
          : 'No day is actually losing you money, so this is about where to lean rather than what to cut.',
        basis: `${all.length} trades with an open time, in UAE time (Asia/Dubai), minimum ${ASK_MIN_N} per day or hour.`,
      };
    },
  },
];

/* ---------------- Ask my data: ang bintana ---------------- */
function openAskData(){
  renderAskList();
  document.getElementById('askDataModal')?.classList.add('open');
}
function closeAskData(){
  document.getElementById('askDataModal')?.classList.remove('open');
}

function renderAskList(){
  const body = document.getElementById('askDataBody');
  if(!body) return;
  const n = _askUniverse().length;
  body.innerHTML = `
    <div class="ask-intro">Every answer below is worked out from your ${n} closed trades. Nothing is guessed, so a number here is always a count of something that happened.</div>
    ` + ASK_GROUPS.map(g => `
      <div class="ask-group">
        <div class="grp-head"><span class="grp-n">${g.n}</span>
          <span class="grp-t">${escapeHtml(g.title)}</span>
          <span class="grp-s">${escapeHtml(g.sub)}</span></div>
        ${ASK_QUESTIONS.filter(q => q.group === g.id).map(q => `
          <button type="button" class="ask-q" id="askq-${q.id}" onclick="runAskQuestion('${q.id}')">
            <span class="ask-q-text">${escapeHtml(q.q)}</span>
            <span class="ask-q-hint">${escapeHtml(q.hint)}</span>
            <span class="ask-a" id="aska-${q.id}"></span>
          </button>`).join('')}
      </div>`).join('');
}

function runAskQuestion(id){
  const q = ASK_QUESTIONS.find(x => x.id === id);
  const slot = document.getElementById('aska-' + id);
  const card = document.getElementById('askq-' + id);
  if(!q || !slot) return;

  // Pangalawang pindot = isara. Isang tanong lang ang bukas sa isang pagkakataon,
  // dahil ang sagot ay mahaba at ang labindalawang bukas ay isang dingding.
  if(card.classList.contains('open')){
    card.classList.remove('open');
    slot.innerHTML = '';
    return;
  }
  document.querySelectorAll('.ask-q.open').forEach(el => {
    el.classList.remove('open');
    const s = el.querySelector('.ask-a');
    if(s) s.innerHTML = '';
  });

  let r;
  try{ r = q.run(); }
  catch(e){
    console.error('Ask my data — ' + id, e);
    r = { notEnough: 'Something went wrong working this one out. The console has the detail.' };
  }
  card.classList.add('open');

  if(r.notEnough){
    slot.innerHTML = `<span class="ask-thin">${escapeHtml(r.notEnough)}</span>`;
    return;
  }
  slot.innerHTML = `
    <span class="ask-head ask-${r.tone || 'flat'}">${escapeHtml(r.headline)}</span>
    <span class="ask-lines">${(r.lines || []).map(l => `<span>${escapeHtml(l)}</span>`).join('')}</span>
    ${r.action ? `<span class="ask-action">${escapeHtml(r.action)}</span>` : ''}
    ${r.basis ? `<span class="ask-basis">Worked out from: ${escapeHtml(r.basis)}</span>` : ''}`;
}
